    -- Nameplates preview
    ["np_preview_title"]   = "Nameplate Preview",
    ["np_preview_hint"]    = "Quick readability: color, cast bar, auras and threat all in one place.",
    ["preview_np_friendly"] = "Ally",
    ["preview_np_target"]  = "Hostile target",
    ["preview_np_boss"]    = "Marked boss",

    -- 3.1.4
    ["wn_314_tooltip_anchor"] = "Tooltip position: new 4-mode anchor — Default, Cursor (follows mouse), Corner (screen corner) and Custom (drag-to-place frame). Configure in Skins → Tooltip.",
    ["wn_314_locale_fix"]     = "Fixed missing tooltip color labels: background and border color pickers in Skins → Tooltip now display correctly in all languages.",

    -- 3.1.5
    ["wn_315_ot_itembutton"] = "Objective Tracker: quest item buttons now correctly hide when their bucket is collapsed (the button is parented to the native tracker, not the block — previously it stayed visible above collapsed buckets).",
    ["wn_315_talkinghead"] = "QOL: the 'Hide Talking Head' toggle is back in the config GUI (QOL → Automations). It now applies instantly without /reload and is reversible — unchecking restores the scrolling dialogue frames.",

    -- 3.1.6
    ["wn_316_party_combat"] = "Party frames: fixed visibility bugs when members join, leave, or the party converts to a raid mid-combat — frames now show/hide reliably in every situation.",
    ["wn_316_raid_combat"] = "Raid frames: fixed frames getting stuck visible or hidden when raid members join or leave during combat — visibility is now handled by a secure, combat-safe system.",
    ["wn_316_roster_repaint"] = "Party & Raid frames: fixed stale info (class color, absorbs, dispel highlight) briefly showing the wrong player after a roster shift, even mid-combat.",
    ["wn_317_cdm_holders"] = "Cooldown Manager: new 'Holders' system — freely move and lock each cooldown viewer (Essential, Utility, Buff Icons, Buff Bars) independently of Blizzard's Edit Mode grid, with live preview icons/bars while empty.",
    ["wn_317_resourcebars_health"] = "Resource Bars: new optional health bar — configurable height, format (%, value or both), class-colored fill, smooth animation and a low-health color threshold.",
    ["wn_317_config_cards"] = "Config UI: the Cooldown & Resource panel got a new Cards layout plus a dedicated Bars tab for all health bar settings.",
    ["wn_316_locale_cdm"] = "Fixed the CD & Resource panel showing raw keys instead of translated text for the Bars tab, placement/live preview cards and the health bar & animations section — translated in all 6 languages.",
    ["wn_316_taint_chat"] = "Fixed a taint error ('secret string value') in the chat frame skin when receiving channel messages.",
    ["wn_316_taint_skyride"] = "Fixed a taint error ('secret number value') in the Skyriding speed bar caused by the game's protected flight/gliding speed values.",
    ["wn_316_durability_pos"] = "Minimap: the gear durability text position is now configurable (corner + X/Y offset) in Interface → General → Info Panel — useful to avoid overlap with the new 12.0.7 expansion button.",

    -- 3.1.7
    ["wn_317_libserialize_namespace"] = "Profiles: the embedded LibSerialize library now uses a private namespace ('TomoSerialize-1.0') instead of the shared 'LibSerialize' name, preventing export/import conflicts with other addons that also embed LibSerialize.",
    ["wn_317_drag_absolute_coords"] = "Movable frames: fixed saved positions drifting or flipping after a drag on Leveling Bar, Movers, AuctionRecipeTracker, Mythic+ Tracker, TomoScore, Frame Anchors, Bag Skin, Castbars, Party/Raid Frame anchors, Compass, Consumable Bar, Loot Browser, Minimap, Objective Tracker, Skyriding bar, Resource Bars and Unit Frames — positions are now saved as stable screen-absolute coordinates.",
    ["wn_317_ot_combat_taint"] = "Objective Tracker: fixed a possible taint error when Blizzard re-shows a collapsed quest bucket block during an in-combat quest update.",
    ["wn_317_deadcode_cleanup"] = "Internal cleanup: removed several unused/disabled modules to reduce addon size — no user-facing features were affected.",
    ["wn_317_raidmanager_fix"] = "Raid Frames: fixed the default Blizzard group leader panel (ready check, raid target markers, convert to raid, ping limit, leave group) being hidden along with the raid frames when 'Hide Blizzard raid frames' is enabled — only the member-frame container is suppressed now, the leader toolbar stays available.",
    ["wn_317_groupmanager_skin"] = "Raid Frames: the 'Skin the group leader panel' option now fully reskins the Blizzard toolbar in the TomoMod dark/mint theme — mode & ping dropdowns, role/group filters, toolbar icons (edit mode, settings, ready check, role poll, countdown), raid marker buttons with their Unit/Ground tabs, and red-styled Leave Group buttons — all while keeping every Blizzard icon intact and toggling live without a reload.",
    ["wn_317_groupmanager_collapsetab"] = "Raid Frames: fixed the group leader panel's collapsed toggle leaving a stray strip on the screen edge, and gave it a proper mint pull-tab look instead of a plain reskinned button.",

    -- 3.1.8
    ["wn_318_bagskin_itemclass_enum"] = "Bag Skin: category matching now uses Blizzard's Enum.ItemClass constants (with numeric fallbacks) instead of hardcoded item class numbers, keeping categorization accurate across clients.",
    ["wn_318_bagskin_cat_order"] = "Bag Skin: default category order updated — Quest Items is now grouped right after Equipment, ahead of Consumables and Trade Goods.",
    ["wn_318_bagskin_cat_foundation"] = "Bag Skin: added the internal groundwork for a future hide/reorder categories option — Miscellaneous and Free Slots always stay visible so no item can ever disappear.",

    -- 3.1.9
    ["wn_3110_actionbar_spelldrag"] = "Action Bars: the 3.1.9 empty-slot drag fix still didn't work for a spell, macro or mount already on a bar (with 'Show empty button slots' off) — moving one onto an empty slot now works during any pickup, without opening the Spellbook/Talents.",
    ["wn_3110_skyride_taint"] = "Skyriding: fixed a recurring taint error on the ground-speed display that could still fire hundreds of times per session despite an earlier fix — the speed calculation is now hardened with an extra safety net so it can no longer throw an error.",
    ["wn_3110_diag_exclusions"] = "Diagnostics: added two new exclusion keywords (merchant refusing to buy an item, looting blocked while Challenge Mode is active) so these normal gameplay messages are no longer logged as bugs.",
    ["wn_319_actionbar_dragfix"] = "Action Bars: fixed spells being impossible to drag onto an empty slot (with 'Show empty button slots' off) unless the Spellbook/Talents window was open — empty slots now reveal themselves during any pickup.",
    ["wn_319_ot_mover_fix"] = "Objective Tracker: fixed the mover position sometimes resetting itself (Blizzard's Edit Mode could silently override it) — dragging it now sticks reliably.",
    ["wn_319_ot_quest_limit"] = "Objective Tracker: fixed the 'Max quests shown' slider having no effect at all in the default Categories layout.",
    ["wn_319_minimap_drift"] = "Minimap: fixed the minimap moving itself to a different spot after a /reload (a scale calculation bug was double-scaling the saved position).",
    ["wn_319_minimap_collector"] = "Minimap: fixed the button collector still hiding other addons' minimap buttons after a reload even when disabled.",
    ["wn_319_minimap_tracking"] = "Minimap: fixed the tracking button sometimes disappearing, and Blizzard's native tracking button staying unclickable after being revealed.",
    ["wn_319_repbar_hide"] = "Reputation Bar: fixed Blizzard's own reputation/honor bar still showing through in some cases when 'Hide Blizzard reputation bar' is enabled.",
    ["wn_319_tooltip_bg"] = "Tooltip: less transparent default background (92% -> 97% opacity) — still fully adjustable via the Background opacity slider.",
    ["wn_319_tooltip_anchor"] = "Tooltip: the 'Custom' position anchor no longer stays visible on screen outside of Layout mode, and a new 'Show/Hide anchor' button was added in Skins -> Tooltip.",
    ["wn_319_diag_copy"] = "Diagnostics: fixed the 'Copy Report' button appearing to do nothing — the export popup could open hidden behind the console window.",

    -- 3.1.11
    ["wn_3111_castbar_deathstuck"] = "Castbars: fixed castbars for target, focus, boss and other non-player units getting stuck visible on screen if the unit died or disappeared without WoW ever firing a matching stop event.",
    ["wn_3111_castbar_targetreset"] = "Castbars: switching target or focus now fully resets the castbar instead of only clearing its fail-state timer, so a leftover cast from the previous unit can no longer stay shown on the newly selected one.",
    ["wn_3111_ot_lfgbutton"] = "Objective Tracker: collapsing a quest category now also hides its 'Find Group' button, not just the item button — both are correctly restored when the category is expanded again.",
    ["wn_3112_score_taint"] = "Mythic+ Scoreboard: fixed a burst of taint errors that could block the end-of-dungeon scoreboard from displaying/positioning itself correctly if the player was still in combat right as the dungeon completed.",
    ["wn_3112_config_resize"] = "Config window: the /tm window can now be resized by dragging its bottom-right corner and scaled with a new 70-130% slider in General — default size increased to 1240x820, with a one-click button to reset both.",
