    -- 3.2.0
    ["wn_320_gsearch"] = "Config window: the sidebar search is now global — it finds matching options across every category and tab, not just the visible page, and clicking a result jumps straight to it with a highlight flash.",
    ["wn_320_panelcache"] = "Config window: switching between category tabs is now instant after the first visit — panels are cached instead of being rebuilt every time.",
    ["wn_320_configlocale"] = "Config window: every remaining hardcoded French label across the settings panels is now fully translatable.",
    ["cfg_tab_cdforge"]           = "Cooldowns",

    -- 3.2.1
    ["wn_321_cdf_intro"] = "New: CooldownForge — build custom cooldown bars per class, tracking spells, items, presets (potions, healthstone...), trinkets or your racial ability, from the new Cooldowns tab (Combat category).",
    ["wn_321_cdf_movers_io"] = "CooldownForge bars can now be dragged into place via the unified Movers manager, and shared between characters with a per-class Import/Export string.",

    -- 3.2.2
    ["wn_322_studio_intro"] = "New: Cooldown Studio — a dedicated full-screen editor for CooldownForge bars, with per-bar Layout/Style/Spells/Visibility/Sharing tabs, opened from the Cooldowns tab.",
    ["wn_322_studio_fix"] = "Cooldown Studio: fixed the window not always displaying above other frames, and its widgets not always inheriting the correct accent color.",
    ["wn_322_studio_visibility"] = "Cooldown Studio: added conditional bar visibility — show or hide a bar based on combat, instance, group or raid status, via simple Indifferent/Yes/No dropdowns in the Visibility tab.",
    ["wn_322_studio_finestyle"] = "Cooldown Studio: added fine-tuning style controls in the Style tab — opacity, border color/thickness, a custom timer color and a drop shadow toggle.",
    ["wn_322_forge_internal"] = "Internal: extracted the shared machinery behind CooldownForge and Cooldown Studio into a new internal Forge library, laying the groundwork for future deep-editing modules — no user-facing changes.",
    ["wn_322_studio_fixes2"] = "Cooldown Studio: fixed sidebar buttons (New/Duplicate/Rename/Delete/blueprints) sometimes not responding to clicks and overflowing their row, fixed Escape closing the window causing a taint error, and fixed the selected tab resetting instead of being remembered when switching bars.",
    ["wn_322_studio_talents"] = "Cooldown Studio: the spell library now also includes your active talents and hero talents, not just spellbook spells, so you can track them on cooldown bars too.",
    ["wn_322_talent_scan_fix"] = "Cooldown Studio: fixed the talent/hero-talent library scan finding nothing in-game — only actually-taken talents are now considered, using the correct API field to read your selected choice.",
    ["wn_322_diag_taintown"] = "Diagnostics: fixed phantom ADDON_ACTION_FORBIDDEN reports (UseToy, SetNote...) getting misattributed to random addons — Diagnostics now takes exclusive ownership of the taint events instead of letting Blizzard's own handling re-propagate them.",
    ["wn_322_actionbars_discover"] = "Action Bars: the Bar management info text now also mentions that expanding a bar reveals its button size and scale controls, making that option easier to find.",
    ["wn_322_tracker_editmode"] = "Objective Tracker: fixed the tracker freezing in place when dragging it while Blizzard's native Edit Mode was active.",
    ["wn_323_studio_preview"] = "Cooldown Studio: the Style tab now shows a live icon preview (same rendering as real bars) cycling through ready/on-cooldown states, so you can see style changes instantly.",
    ["wn_323_studio_copystyle"] = "Cooldown Studio: added a 'Copy style from...' button in the Style tab to copy just the visual style from another bar without touching spells, position or layout.",
    ["wn_323_studio_create"] = "Cooldown Studio: '+ New' now asks for the bar's name up front instead of creating a placeholder you then have to rename, and the rename/create popups now show reliably above the window with the name field auto-focused.",
    ["wn_323_slider_entry"] = "Config sliders: right-click a value to type an exact number, Ctrl+click to reset to default, with a tooltip reminder for both.",
    ["wn_323_petbar_editmode"] = "Action Bars: the Pet and Stance bars can now be selected and dragged in Edit Mode even when hidden at rest (no pet/no stances).",
    ["wn_324_studio_real_icons"] = "Cooldown Studio: the Style tab preview now uses real icons — the bar's own spells first, then your class's spellbook and talents — instead of three hardcoded demo icons from unrelated classes.",
    ["wn_324_chat_contacts"] = "Chat: the chat sidebar gained a Contacts button that opens Blizzard's friends list in one click, restoring an entry point the skin's hidden native social button had removed.",
    ["wn_324_editbox_scrollbar"] = "Config: multi-line text boxes (import/export, notes...) no longer show Blizzard's gold arrow scrollbar — they now use the addon's own thin accent scrollbar and support the mouse wheel.",
    ["wn_325_friends_window"] = "Contacts: the friends window is now fully themed instead of being a half-done pass — flat dark body, accent border drawn above the list, restyled title and a plain accent close button.",
    ["wn_325_friends_tabs"] = "Contacts: the bottom tabs and the Friends / Recent Allies / Recruit A Friend sub-tabs lost their gold plates, and now show an accent underline and label on the selected one.",
    ["wn_325_friends_buttons"] = "Contacts: every button in the window (Add Friend, Send Message, the Who tab buttons, Convert to Raid, Raid Info, Join Queue) now shares one flat accent style that brightens on hover, and the two contact buttons split the bottom row evenly.",
    ["wn_325_friends_toggle"] = "Contacts: turning the skin off in the settings now restores Blizzard's look immediately instead of needing a reload.",
    ["wn_325_cdf_radial"] = "CooldownForge: cooldown bars can now arrange their icons on a circle instead of a line — set the radius, start angle, arc amplitude and direction from the new Layout mode.",
    ["wn_325_cdf_spacing"] = "CooldownForge: icon spacing is now two separate values — along the row and between wrapped rows — and the maximum was raised from 16 to 64 px.",
    ["wn_325_cdf_glow"] = "CooldownForge: glow can now trigger on a chosen condition — when the spell is ready, while a buff is active on you (with an optional buff ID for trinkets/talents), or always — set per bar or per spell.",
    ["wn_325_cdf_hidecd"] = "CooldownForge: a bar can now hide each icon while it is on cooldown, with the remaining icons closing the gap; it reflows only when the set of ready spells changes.",
    ["wn_326_whatsnew_stuck"] = "What's New: closing this popup with Escape used to leave the screen dimmed and the mouse dead, and the version unmarked so it came back next login. Every close path — X, button, Escape — now goes through one place that clears the dimmer and remembers the version.",
    ["wn_326_whatsnew_escape"] = "What's New: Escape is now captured by the window itself instead of Blizzard's UISpecialFrames, removing a taint path through the game menu; every other key still passes through.",
    ["wn_326_whatsnew_gates"] = "What's New: the popup now waits for a clear moment — never over a cinematic, a movie or a fight — and skips a character's very first login entirely, so it no longer greets you mid intro sequence.",
    ["wn_326_tracker_empty"] = "Objective Tracker: with nothing tracked, the tracker no longer leaves a dark panel covering most of the screen — it now collapses to its header, and 'Hide when empty' is on by default (existing profiles are updated once; turning it back off sticks).",
    ["wn_326_tracker_drag"] = "Objective Tracker: the panel can be dragged downwards again — screen clamping was applied to Blizzard's oversized tracker frame, whose bottom edge already sat off-screen, so every downward move was refused.",
    ["wn_326_repbar_drag"] = "Reputation bar: fixed the bar showing its unlock border in Layout mode but refusing to be grabbed — it never had mouse input enabled, so dragging could not start.",
    -- Cooldown Manager holders (Movers / layout mode)
    ["mover_cdm"]                        = "Cooldown Manager",
    ["cdm_drag_hint"]                    = "Drag to move",
    ["cdm_preview_aura"]                 = "Aura",

    ["wn_326_suite_card"] = "Config: the dashboard gained a 'Tomo suite' card presenting TomoBoss (boss timers with spoken callouts) — a shortcut to its options if it is installed, a copyable address and a permanent 'Don't show again' otherwise.",

    ["wn_330_tracker_delve"] = "Objective Tracker: inside a Delve the tracker showed nothing at all — no stage, no criteria, no progress. 'Hide when empty' only counted quest blocks, while a Delve tracks its progress in the scenario module, which that count deliberately leaves out, so the whole panel was hidden. Delves, scenarios and bonus objectives now count as content, and the panel sizes itself to them when they are alone on screen.",
    ["wn_330_tracker_delve_place"] = "Objective Tracker: with 'Hide when empty' turned off, the panel stayed but the delve block was never positioned inside it — the empty case returned before the pass that places it. Scenario and delve modules are now placed first, whatever else is tracked.",
    ["wn_330_cdf_unusable"] = "CooldownForge: an icon can now tint itself when the spell is off cooldown but cannot be cast right now — no rage, wrong form, missing reagent. Choose no effect (the default), grey out, or grey out plus a blue tint when the missing resource is the blocker, per bar and per spell.",
    ["wn_330_cdf_glow_usable"] = "CooldownForge: glow gained a 'when the spell is usable' condition — ready plus castability, so a resource-starved spell stops glowing while it waits instead of inviting a press that would fail.",
    ["wn_330_cdf_hide_unusable"] = "CooldownForge: a bar can also drop an icon entirely while you cannot afford it, next to the existing 'hide while on cooldown' filter. The two are independent and stack, and the remaining icons close the gap.",
    ["wn_330_cp_charged"] = "Resource Bars: supercharged combo points are now shown as such — the charged slot is marked whether it is filled or not, so you can see where the charge sits before spending it. The color is yours to pick in CD & Resource → Colors, red by default.",
    ["wn_330_colorpicker"] = "Config: the color picker kept opening behind the settings window and Cooldown Studio, which looked like the swatch did nothing. It now opens above them, right next to the swatch you clicked instead of at the centre of the screen.",
    ["wn_330_locale_escapes"] = "Localization: the Compass options printed raw escape codes where accents belonged — \"dxC3xA9filer\", \"xC3x89chelle\", \"Large (xC2xB190xC2xB0)\". Those strings used an escape syntax the game's Lua does not understand and printed literally; they are plain text again, in all six languages.",
    ["wn_330_diag_filters"] = "Diagnostics: being rooted in place and trying to mail a soulbound item were logged as errors in the report. Both are normal game feedback, and are now filtered out like the rest of it.",
    ["wn_330_tooltip_info"] = "Tooltip: unit tooltips now carry a real information layer — guild rank, the unit's current target, Mythic+ score, mount, movement speed and location, plus raid marker, role and class icons on the name line. Every line has its own toggle in Skins → Tooltip.",
    ["wn_330_tooltip_inspect"] = "Tooltip: hovering a player now shows their equipped item level and their specialization. Both require an inspect, so they appear when the player is in range; the item level is colored by the gap to your own rather than by season thresholds that go stale every patch.",
    ["wn_330_tooltip_border"] = "Tooltip: the border can take the unit's color — class color for a player, hostile / neutral / friendly for an NPC — and the level line is recolored by difficulty, red for a boss or a '??' unit.",
    ["wn_330_tooltip_bar"] = "Tooltip: the health bar is now hidden by default, since the information layer replaces it. Existing profiles are updated once; unticking the option puts the bar back and it sticks.",
    ["wn_330_pf_leader"] = "Party frames: the group leader is now marked with a crown above their frame, with its own toggle and size slider.",
    ["wn_330_stance_bar"] = "Action Bars: classes with no shapeshift forms got a stance bar with ten empty squares on it, and unchecking 'show empty button slots' made the whole stance bar vanish. The bar now only appears when you actually have forms, and shows exactly as many buttons as you have.",
    ["wn_330_leveling_panel"] = "Leveling bar: hovering it now opens a styled panel instead of a tooltip, showing level, XP, XP remaining, progress, rested, XP/h, time to level, XP gained since your last ding and the last quest's contribution. It flips below the bar when there is no room above.",
    ["wn_330_bags_click"] = "Bags: disenchanting, milling or prospecting from the bag skin took two attempts — the press consumed the targeting cursor and the release picked the item up instead. It works on the first try now, and dragging is unaffected.",
    ["wn_330_bags_layout"] = "Bags: the 'Categories' layout has been removed, leaving Combined Grid and Separate Bags. A profile still set to it is moved onto the combined grid once.",
    ["wn_330_chat_copy"] = "Chat: the per-message copy icon put a placeholder glyph in front of every line because its texture never resolved. The option is removed, and cleared once for anyone who had it on.",

    ["wn_331_tooltip_secret"] = "Tooltip: the whole unit information layer added in 3.3.0 never appeared in Midnight — no guild rank, target, Mythic+ score, mount, speed, location, item level, specialization or name-line icons. The layer reads the unit token back from the tooltip, the game now hands that token out as a protected value, and the guard rejected it, so nothing was ever written.",
    ["wn_331_tooltip_border"] = "Tooltip: the unit-colored border was off for the same reason — it read the token through its own guard and gave up, so every unit fell back to the configured border color, which looked exactly like the option doing nothing.",
    ["wn_331_tooltip_target"] = "Tooltip: the target line was dropped for any player whose name comes back protected, which is most of them. The name is no longer wrapped in a color escape — building that string counts as reading the name — and the color goes through the tooltip's own color arguments instead. Identical on screen, and it works now.",
    ["wn_331_tooltip_guards"] = "Tooltip: the safety guards could themselves raise an error. One compared the value to an empty string before checking whether it was protected, so it crashed on exactly the values it existed to catch, and around twenty true/false tests (does the unit exist, is it a player, can it be inspected…) were compared raw. All of them are checked in the right order now.",
    ["wn_331_inspect"] = "Tooltip: item level and specialization are back with the rest of it — the inspect engine ran the same unguarded comparisons on every eligibility test, and stood down on a protected value before ever sending a request.",
    ["wn_327_tracker_progressbars"] = "Objective Tracker: quest progress bars (kill counts, enemy forces, scenario and delve criteria) are back — a bar is no longer swept away as orphaned when its block is only reachable through an anchor, it survives collapsing and re-expanding its bucket, and the bars that stay are now themed like the rest of the tracker.",
    ["wn_327_tracker_position"] = "Objective Tracker: a tracker moved with Blizzard's own Edit Mode snapped back to its old spot on the next reload — that position was never written to the addon's database. It is saved when the Edit Mode session ends now, and a tracker scaled above or below 100% no longer creeps across the screen a little more on every reload.",
    ["wn_327_minimap_indicators"] = "Minimap: the instance difficulty flag stayed visible outside instances, because re-anchoring the native indicators also forced them visible and overrode Blizzard's own rule. They follow Blizzard's visibility again — and the expansion button no longer stays invisible for good once turned off and back on.",
    ["wn_327_resourcebar_frozen"] ="Resource Bars: the centered power bar stayed stuck on the value it was built with — 0 rage, 0 energy — for every spec whose only resource is the primary one (Warrior, Priest, Fire Mage, Mistweaver, Havoc...), while the unit frame showed the real amount. It refreshes like every other bar again.",
    ["wn_327_profile_rename"] ="Profiles: renaming or duplicating a profile did nothing at all — Blizzard's 11.2 popup rewrite removed the field the accept handler read the typed name from. Both work again, and Enter now confirms like the accept button.",
    ["wn_327_cds_rename"] = "Cooldown Studio: same fix for the Rename bar and '+ New' popups — the name you typed was ignored, so renaming did nothing and every new bar came out called 'Nouvelle barre'.",
    ["wn_327_popup_layer"] = "Popups: the reload prompt, the import / export dialogs and every profile confirmation used to render behind the config window and Cooldown Studio, looking like nothing had happened. They are now raised above whichever TomoMod window is open.",
    ["wn_327_profile_refresh"] = "Profiles: creating, deleting, renaming or duplicating a profile now refreshes the list on screen instead of leaving the previous one displayed from the panel cache.",
    ["wn_327_import_perf"] = "Profiles: importing is noticeably faster — the string decoded for the preview is reused on accept instead of being decoded a second time, which was most of the freeze when clicking Import.",
    ["wn_327_gui_split"] = "Config: Profiles and Diagnostics are separate sidebar categories again instead of being grouped under Tools, each with its own icon and description; old links to Tools still work.",

    -- =====================
    -- 3.3.2 — What's New
    -- =====================
    ["wn_332_perf_auras"] = "Performance: the Aura Tracker and the Buff Skin now only listen to your own aura changes. They only ever acted on you, but they were being woken for every unit whose auras changed — twenty-plus raid members plus every visible nameplate, continuously — just to check the unit and drop it. The game filters those out before any of our code runs now.",
    ["wn_332_perf_castbar"] = "Performance: same for the castbar's latency tracking, which was being woken by every cast of every visible unit — an entire trash pull's worth of abilities — where only your own casts ever mattered.",
    ["wn_332_perf_gc"] = "Performance: the Aura Tracker was the biggest source of memory churn on the overlay. Its scan and layout ran several times a second in combat and threw away a pile of temporary tables on every pass; they now reuse the same working tables. Nothing on screen changed.",
    ["wn_332_aura_order"] = "Aura Tracker: two auras applied on the same cast with the same duration could visibly swap places between refreshes, because nothing decided their order. It is stable now.",
    ["wn_332_skyride_leak"] = "Skyriding: /tm skyride built a second copy of the bar every time it was used. The old one stayed on screen, no longer connected to anything and impossible to hide, because the game never reclaims a frame. The bar is built once now and the command just re-applies your settings to it.",
    ["wn_332_skyride_ticker"] = "Skyriding: the same command also left a permanent 4-per-second update running behind it each time, with no way left to stop it. They are no longer duplicated, and the update stops when the module is turned off instead of polling a hidden bar.",
    ["wn_332_tooltip_incombat"] = "Tooltip: item level and specialization disappeared from every tooltip the moment a fight started, and came back when it ended. The range test the inspect engine finished on is one the game refuses to answer for addons during combat, so every unit was judged out of range for the whole pull — while the taint log filled up with one blocked call per hover. It now uses a test that works in combat.",
    ["wn_332_tooltip_backoff"] = "Tooltip: the replacement range test is less precise (it sees much further than an inspect can actually reach), so a player too far away to answer is now remembered and left alone for twenty seconds instead of being asked again on every tooltip. Only one inspect can be in flight at a time, and one out-of-range player used to take that slot over and over. A tooltip that never got an answer also stopped being stuck on 'loading'.",
    ["wn_332_diag_nopath"] = "Diagnostics: charging across a gap, leaping onto a ledge or sending a pet somewhere it cannot walk was logged as an error in the report. 'No path available' is normal game feedback, and is now filtered out in all six languages.",
    ["wn_332_locale_castbar"] = "Config: the Castbars panel's main checkbox was labelled 'Enable consumable bar' in every language — two different options had been given the same translation key, and the consumable one won. Each has its own now.",
    ["wn_332_locale_translations"] = "Localization: 173 strings per language translated into German, Spanish, Italian and Portuguese — Cooldown Manager advanced/visibility settings, objective tracker quest categories, the chat frame UI, movers and cursor textures — plus the 49 chat frame UI strings in French. They were quietly falling back to English rather than showing an error, so nobody reported them.",
    ["wn_332_locale_search"] = "Config: the search box showed the raw text 'gs_no_results' instead of 'No matching option' when nothing matched. The message is defined in all six languages now.",
    ["wn_332_package"] = "Packaging: the download no longer includes the bundled libraries' test suites, examples, generated documentation and readme files. None of it was ever loaded by the addon.",
    ["wn_332_companion_panel"] = "Pet Reminder: the module that warns you when your pet is missing or dead finally has a settings panel, under QOL. Enabling it, its size, its scale, whether it shows the icon, the text or both, and where it sits on screen were previously only reachable by editing a file by hand.",
    ["wn_332_companion_travel"] = "Pet Reminder: it could stay on screen, at four times its size, for an entire flight. It only ever checked whether you were flying at moments when you were still standing on the ground, and nothing could hide it afterwards. It is now hidden while flying, on a flight path and in a vehicle — and on a ground mount too, which you can turn back off.",
    ["wn_332_companion_locale"] = "Pet Reminder: 'Pet missing' and 'Pet dead' were English whatever your client's language was. Both are translated now, along with everything in the new panel.",

    -- =====================
    -- 3.3.3 — What's New
    -- =====================
    ["wn_333_summon_stuck"] = "Party & raid frames: the incoming summon icon stayed on the frame until you reloaded. Once you accept or decline, the game keeps reporting the summon's last state instead of clearing it, so the icon was describing something that had stopped existing minutes earlier. It now checks whether a summon is actually still open before showing anything.",
    ["wn_333_summon_roster"] = "Party & raid frames: when the group changed, a summon icon could stay on a frame that now belonged to a different player. The summon state is re-read on every roster change and after zoning, and it is refreshed with the rest of the frame instead of only when the game announces a change.",
    ["wn_333_defensives_party"] = "Party frames: defensive cooldowns active on each member are now shown, which previously only existed on raid frames — and there it was a single icon with no duration and no indication of what it was.",
    ["wn_333_defensives_categories"] = "Party & raid frames: defensives are split into externals (cast on this player — Ironbark, Life Cocoon, Pain Suppression), raid-wide (Rallying Cry, Darkness, Anti-Magic Zone) and personals (Divine Shield, Ice Block, Barkskin), each with its own toggle. Fifty spells, sorted so externals come first, with remaining time and a border colored by category.",
    ["wn_333_defensives_defaults"] = "Party & raid frames: only externals are shown by default. A raid-wide cooldown lights up every frame at once — exactly when you are least able to read them — and personals are constant. Both can be turned on.",
    ["wn_333_defensives_size"] = "Raid frames: the defensive icon size slider only took effect after a reload. It applies as you drag it now.",
    ["wn_333_hots_drift"] = "Party & raid frames: the two sets of frames disagreed about which heal-over-time effects to show. Blessing of Summer, Cloudburst Totem and Enveloping Breath appeared on party frames and not on raid frames — the same buff, on the same player, visible on one and not the other. There is one list now, covering all six healing classes.",
    ["wn_333_dispel_border"] = "Party & raid frames: the dispel highlight's border thickness is now a slider, 1 to 6. It grows outwards from the frame edge, so a thicker border never eats into the health bar, and the default looks exactly like before.",
    ["wn_333_stance_grid"] = "Action Bars: with 'show empty button slots' off, the stance bar could still put ten empty squares on screen, and they stayed there until you changed stance. The pass that reveals empty slots while you drag a spell was also running over the stance and pet bars, whose buttons are not action slots — so it judged every one of them empty and showed them, while the pass that hides them again deliberately skips those two bars, leaving nothing to put them back.",
    ["wn_333_diag_display"] = "Diagnostics: reports now include your resolution, display mode and UI scale — and flag the case where the scale has been set by something other than the game's own options. Above 1200 pixels tall the client will not scale the interface down far enough on its own, so high-resolution setups end up rescaled by hand or by another addon, and that was invisible in a report.",
    ["wn_333_diag_scalechange"] = "Diagnostics: a scale or resolution change during your session is logged with its before and after values, so a rescale shows up next to the errors it may have caused. That rescale is reapplied after every loading screen, which is when it tends to break things.",
    ["wn_333_diag_perf"] = "Diagnostics: reports now carry framerate (current, and the session's minimum, average and maximum) and latency, and every captured error records the framerate at the moment it fired. An error that only appears on a stuttering client is a timing problem rather than a broken feature, and nothing in a report used to tell them apart.",
    ["wn_333_diag_scale_expected"] = "Diagnostics: the report claimed your interface scale had been set by a macro or another addon on almost every setup. When the game's own UI scale option is off, the value it was comparing against is not the one the game is using, so a perfectly ordinary configuration was flagged. It now works out what the scale should be for your resolution and settings, prints it, and warns only when it genuinely differs.",
    ["wn_333_diag_settle"] = "Diagnostics: the scale the game applies for itself while you log in was recorded in every report as a mid-session rescale. The display capture now waits four seconds for the client to settle before taking a reading, so the only scale entry left in a report is one that actually needs explaining.",
    ["wn_333_diag_mode"] = "Diagnostics: when the report cannot work out your display mode it now prints the raw values the game gave it instead of a bare question mark — those setting names change between expansions, and a '?' on its own could not be diagnosed without asking you for more. Windowed-fullscreen and maximized windows are recognised in more cases, and addon versions no longer read 'vv1.2.3'.",
    ["wn_333_shared"] = "Internal: the party and raid frames kept two copies of the same 250 lines — the summon logic, the heal-over-time list, the defensive tracking. All three bugs above came from that: a fix applied to one copy and not the other. They share one implementation now.",
    -- =====================
    -- 3.6.3 — What's New
    -- =====================
    ["wn_363_aura_display"] = "Fix — Aura icons are showing again on every frame that draws them through the game's own aura display: Healer Studio indicators, the party and raid heal-over-time rows, debuff and dispel indicators, nameplate auras and unit frame auras. The display behind them was given a unit but never switched on, so it had everything it needed and still showed nothing.",
    ["wn_363_aura_spacing"] = "Fix — The spacing you set between aura icons is applied again. It was being passed to the game under the old option names, which the current aura display ignores, so every row was drawn at the game's own default gap whatever you had chosen.",
    ["wn_363_aura_size"] = "Fix — Changing the size or the number of aura icons takes effect straight away again. The change used to be applied by rebuilding the icon group, which the game no longer allows, so the icons kept their previous size until the frames were rebuilt — in practice, until a reload. Icons already on screen are now resized on the spot, not only the ones that appear afterwards.",
    ["wn_363_aura_recycle"] = "Fix — A party or raid cell, or a nameplate, that is handed to a new unit no longer keeps showing the previous unit's auras. Releasing a frame now switches its aura display off, which clears its icons, instead of only detaching the unit and leaving it watching.",
    ["wn_363_healer_studio"] = "Fix — Healer Studio benefits from all of the above: its indicators appear as soon as a spell is selected, the size slider moves the icons that are already on screen, and turning a spell off clears its icon immediately instead of leaving it behind on a recycled cell.",
    ["wn_363_probe"] = "Fix — Cooldown Studio's buff tracking now shuts down completely when an icon stops tracking a buff, instead of leaving an unused watcher running for the rest of the session.",
    ["wn_363_revive_color"] = "Fix — A resurrected player no longer keeps the grey death colour on their party or raid frame. The frame was repainted while the game still reported the player as dead, and nothing repainted it afterwards, so the wrong colour stayed until a reload. It is now repainted when the player's state actually changes, which also covers someone who drops offline and comes back.",
    ["wn_363_tomoscore_keys"] = "Fix — The end-of-dungeon scoreboard no longer blocks your movement keys. It opens on its own when a key finishes, and it was set to react to the keyboard so Escape could close it, which could stop your movement keys from reaching the game. It is mouse-only again: close it with its button, and every binding keeps working while it is on screen.",
    ["wn_363_raid_event_gate"] = "Changed — Raid frames no longer listen for health, power and aura updates while you are not in a raid. The module was being woken by every unit in the game — party members, nameplates, bosses, your target — to look for a raid frame that could not exist. It now subscribes when you join a raid and stops when you leave, including in the middle of a fight.",
    ["wn_363_leveling_bar"] = "Fix — The leveling bar can be turned on again. Its frame was published under the same global name as the module that drives it, so building the bar once replaced the module: from then on the option, the width and height sliders, the mover and /tm sr all silently did nothing, and ticking the box left the setting switched on with no bar on screen.",
    ["wn_363_dk_runes"] = "Changed — Death Knight runes are drawn with a flat fill instead of the shared gradient bar texture. The gradient reads as a highlight on a tall health bar, but across six short rune segments it only muddied the colour.",
    ["wn_363_forge_drag"] = "Changed — In AstralForge, dropping an element now attaches it to the nearest corner, edge or centre of whatever it is sitting on, exactly as Healer Studio already did. The attachment point never used to change, so pushing a piece into a corner left it hanging from the middle of the frame by a long offset, and it slid out of place as soon as the frame was resized. Elements you had deliberately attached to another element rather than to the frame keep that link.",
    -- =====================
    -- 3.6.2 — What's New
    -- =====================
    ["wn_362_healer_studio"] = "New — Healer Studio: pick exactly which of your own heal-over-time effects, shields and healer buffs appear on the party and raid frames, and place each icon wherever you want on the cell. It replaces the fixed row of HoT icons with your own layout, and Party and Raid each keep their own. Available for Priest, Druid, Paladin, Shaman, Monk and Evoker.",
    ["wn_362_healer_editor"] = "New — The layout is built in a dedicated window, opened from Party Frames or Raid Frames under Features. Drag an icon onto the cell preview to place it, or set its size, its anchor and its exact offsets with the controls next to it — everything is saved as you go, with no Apply button and no reload. A starter preset switches on the first few spells of your class, and you can lay out any healer class, not only the one you are playing.",
    ["wn_362_healer_preview"] = "New — The preview in Healer Studio is your own cell, enlarged: it uses the width and height your party or raid frames are actually set to, so what you place is what you get in game. Dropping an icon snaps it to the nearest corner, edge or centre, which means it stays where you put it if you resize your frames later.",
    ["wn_362_healer_profile"] = "New — Healer Studio layouts are stored with the rest of your settings, so they follow a profile export and come back with an import instead of being dropped along the way.",
    ["wn_362_healer_spec"] = "New — By default the advanced layout only applies while you are in a healer specialization, so your Shadow or Feral spec keeps the normal HoT row without you having to switch anything. Leaving or entering a healer spec swaps the two over on its own, without a reload.",
    ["wn_362_healer_legacy"] = "Note — Nothing changes unless you turn Healer Studio on: it is off for both party and raid frames, and the classic HoT row keeps working exactly as before. You can also turn the classic row off entirely and keep only your own placed icons.",
    ["wn_362_vault_types"] = "Fix — The Great Vault preview in Mythic Hub now reads its Raids, Dungeons and Delves rows from Blizzard's official reward types instead of guessing them from whatever the weekly rewards API happened to return, so the Delves row no longer comes up empty or filled with another row's activities.",
    ["wn_362_vault_progress"] = "Fix — The Great Vault preview no longer forces a refresh of Blizzard's own Weekly Rewards window before reading your progress. That refresh resets activity progress to zero while a previous reward is still waiting to be claimed, which made completed dungeons, raid bosses and delves show up as 0.",
    ["wn_362_vault_slots"] = "Fix — Each Great Vault row now asks the game for its own activities and orders them by reward tier, so the extra entries the API returns alongside the real rows (bonus and catch-up rewards) can no longer take over a visible slot.",
    ["wn_362_ab_release"] = "Fix — Action buttons respond on the release of a click again. TomoMod's own buttons were missing the secure release attribute Blizzard installs on its action buttons, so with Cast on Key Press turned off nothing was cast at all, and press-and-hold spells such as Evoker empowered casts could be started but never released.",
    ["wn_362_ab_release_gse"] = "Fix — A button that was used for a GSE sequence now returns to the normal press and release behaviour of a regular action as soon as its action changes, instead of keeping the GSE contract until the next reload.",
    ["wn_362_ab_cooldown_push"] = "Fix — Action button cooldown swipes now follow the game exactly. TomoMod kept a short-lived copy of each button's cooldown state and reused it for up to a fraction of a second, which could hide a cooldown starting or ending — most noticeably on short cooldowns and during the brief window while the server confirms a cast. Cooldown state is now read fresh every time, while repeated lookups within one refresh pass are still shared.",
    ["wn_362_ab_counts"] = "Fix — Action bar charge and stack counters no longer trigger a full refresh of every button for each aura or charge event. On large Mythic+ pulls those events arrive in bursts; in combat the work is now grouped a few times per second instead, which keeps key presses responsive. Out of combat nothing is throttled.",
    ["wn_362_ab_glow"] = "Fix — The safety pass that clears leftover proc glows no longer rescans every visible action button for each glow event. The button that lost its glow is still updated instantly, and the full check now runs at most ten times per second, so proc-heavy fights no longer cost input latency.",
    ["wn_362_ab_assist_rotation"] = "Changed — Assisted Combat now locates its action buttons through the game's dedicated Assisted Combat slot API instead of searching every bar for the currently suggested spell, so a change of suggestion no longer touches unrelated buttons.",
    ["wn_362_ab_assist_load"] = "Fix — A change of Assisted Combat suggestion no longer refreshes every TomoMod action button, and TomoMod no longer hooks a Blizzard highlight function that can be called at rotation speed during combat. Together these were the largest source of extra work while the One Button rotation was active.",
    ["wn_362_ab_assist_highlight"] = "Fix — The Assisted Combat highlight is now cleared when the game stops suggesting a spell, and toggling Blizzard's assisted highlight option takes effect immediately instead of requiring a reload.",
    ["wn_362_rb_toggles"] = "New — Two new options under Animations & Power Bar: one turns off the glow that appears when a class resource reaches its maximum, the other turns off the supercharged combo point art for Rogues. Both are on by default, and switching either off immediately restores the normal look of the points already on screen.",
    ["wn_362_rb_glow_stop"] = "Fix — The maximum-resource glow no longer lingers when it should be gone. It is now stopped when the option is switched off and when the class resource display is rebuilt, instead of being left running on a frame that has already been discarded.",
    -- =====================
    -- 3.6.1 — What's New
    -- =====================
    ["wn_361_assist"] = "Fix — Blizzard's Assisted Combat rotation frame now shows and updates correctly on TomoMod action buttons instead of freezing on the button's unsynced Lua action field.",
    ["wn_361_keydown"] = "Fix — TomoMod's Cast on Key Press setting now stays in sync with Blizzard's own input CVar, fixing a first-press-after-login input that could be silently swallowed.",
    ["wn_361_safewindow"] = "Fix — Combat-deferred override bindings from a mid-combat /reload now reliably replay after combat instead of relying on a safety window that could itself allow blocked actions.",
    ["wn_361_strata"] = "Fix — Action Bar 1, Pet and Stance buttons no longer render above full-screen Blizzard panels such as the World Map.",
    ["wn_361_flyouts"] = "Fix — Spell flyouts such as Mage Portal/Teleport open and cast correctly again; TomoMod no longer resizes native flyout buttons in a way that could taint the secure flyout.",
    ["wn_361_flyouts_cast"] = "Fix — Native flyout popup buttons are no longer hooked or written to at all, since even cosmetic changes could taint Blizzard's protected CastSpellByID/CastSpellByName cast path.",
    ["wn_361_flyout_secure"] = "Fix — TomoMod action buttons now refresh their spell flyout through Blizzard's own UpdateFlyout inside a secure call, and TomoMod's replacement popup methods have been removed from owned buttons. The flyout arrow, the popup it opens and the cast that follows now stay entirely on Blizzard's protected path.",
    ["wn_361_bar6_quarantine"] = "Fix — Spell flyouts on Bar 6 no longer risk becoming forbidden to cast: that bar now uses TomoMod's own secure flyout instead of Blizzard's native one, since the native flyout could still pick up taint specifically when opened from Bar 6. Every other bar keeps using Blizzard's native flyout.",
    ["wn_361_flyout_keybind"] = "Fix — Pressing an assigned keybind to open or close a TomoMod flyout button now works correctly; only a mouse click was recognized before.",
    ["wn_361_flyout_discovery"] = "Fix — TomoMod now also scans the actual action slots on the quarantined bar to find its flyouts, instead of relying only on spellbook enumeration, so flyouts placed there always show the correct known/unknown slot icons.",
    ["wn_361_vehicle_mover"] = "New — Leave Vehicle now has its own mover in layout mode, so it can be placed anywhere on screen instead of being fixed above Action Bar 1. Its position is saved with your profile, and it still defaults to just above Bar 1 until you move it.",
    ["wn_361_vehicle_state"] = "Changed — The Leave Vehicle button is now shown whenever you can actually leave the vehicle, instead of whenever a vehicle UI is displayed, so it no longer appears for vehicles you cannot exit.",
    ["wn_361_vehicle_taxi"] = "Fix — Blizzard's own Leave Vehicle button is now hidden only while TomoMod's secure replacement is usable, so a working exit control remains available on taxi flights and in vehicles that do not allow an early exit.",
    ["wn_361_tracker"] = "Fix — Objective Tracker quest blocks skipped during combat now finish laying out automatically once combat ends, instead of staying overlapped until an unrelated quest update.",
    ["wn_361_buttonbag"] = "Fix — The minimap addon-button collector no longer forgets the buttons it has already gathered when it rescans, so addons that register their button later open a new row instead of stacking on top of the first one.",
    ["wn_361_trackdupe"] = "Fix — The Tracking panel no longer lists the same entry twice (Banker showed up on two rows). Tracking filters the game reports under the same name are merged into a single row that toggles them together.",
    ["wn_361_micromenu_native"] = "Fix — TomoMod no longer builds its own container, reparents buttons or touches layout for Blizzard's Micro Menu, and the old standalone Micro Bar module has been removed entirely.",
    ["wn_361_micromenu_gui"] = "Changed — The Bag & Micro Menu options panel now shows a compact Group Finder eye section instead of the old Micro Bar builder, with just an ON/OFF toggle and a size slider.",
    ["wn_361_lfgeye_fix"] = "Fix — The Group Finder eye no longer disappears when the Micro Menu fades out on mouseover; it now has its own visibility and scale handling, refreshed automatically when you enter the world, queue for something, or a dungeon/battleground pops.",
    ["wn_361_validation"] = "Tested — Assisted Combat, key-down casting, combat-reload bindings, Bar 1/Pet/Stance strata near the World Map, spell flyouts, Objective Tracker combat deferral, and the Group Finder eye across Micro Menu fade and LFG events were validated in game.",
    -- =====================
    -- 3.6.0 — What's New
    -- =====================
    ["wn_360_foundation"] = "Changed — ActionBars now use a zero-taint ownership model: TomoMod keeps addon-owned buttons out of Blizzard's native action-button broadcaster and leaves protected Blizzard bar state under Blizzard ownership.",
    ["wn_360_nativebars"] = "Fix — Blizzard standard action bars stay alive for secure paging but are visually suppressed, so only TomoMod bars are shown without freezing their runtime state.",
    ["wn_360_specialvisuals"] = "Fix — Blizzard Stance, Pet and Possess bars remain functional underneath while their duplicate textures, text, cooldown swipes, autocast overlays, checked borders and flash effects are masked.",
    ["wn_360_stance"] = "Fix — TomoMod Stance buttons now use independent secure spell actions and remain clickable for Druid forms, Paladin auras and Warrior stances.",
    ["wn_360_pet"] = "Fix — TomoMod Pet buttons now use independent secure pet actions; normal pet commands, abilities and right-click autocast toggles remain usable without relying on the visible Blizzard Pet Bar.",
    ["wn_360_possess"] = "Fix — Possession and vehicle states continue through Action Bar 1's secure paging instead of requiring TomoMod to manipulate Blizzard's PossessActionBar.",
    ["wn_360_paging"] = "Fix — Action Bar 1 reads its current secure action slot directly, keeping form, vehicle, override and possess paging live instead of freezing on a Lua-side snapshot.",
    ["wn_360_formsafe"] = "Fix — Druid Human/Cat/Bear changes now update Action Bar 1 correctly in and out of combat with no protected-action or secret cooldown errors observed in testing.",
    ["wn_360_extra"] = "Fix — Extra Action keeps Blizzard's secure gameplay behavior while TomoMod provides the visible button, its own GCD/charges and a click-safe presentation without the invisible native hitbox stealing input.",
    ["wn_360_zone"] = "Fix — Zone Ability keeps live state-dependent icons, GCD and charges, disappears when no longer active, and preserves native click behavior for quest abilities that require it.",
    ["wn_360_vehicle"] = "Fix — Leave Vehicle remains a secure TomoMod action with the shared ActionBar skin while Blizzard taxi behavior stays available when needed.",
    ["wn_360_gcd"] = "Fix — Native Stance/Aura/Posture GCD remnants are visually masked without touching Blizzard's cooldown values or protected button state.",
    ["wn_360_petvisuals"] = "Fix — The remaining Blizzard PetBar checked-state borders, flash effects and autocast overlays are now hidden while the underlying pet state stays fully functional.",
    ["wn_360_skin"] = "Changed — Extra Action, Zone Ability and Leave Vehicle now share the same regular TomoMod action-button skin pipeline as the rest of the bars.",
    ["wn_360_flyouts"] = "Fix — Spell flyouts open correctly again from TomoMod Action Bars, including Mage portals and Hunter traps.",
    ["wn_360_installer"] = "Fix — The first-run installer now loads reliably on fresh installs and waits until cinematics, movies and combat are over before appearing.",
    ["wn_360_rolesafe"] = "Fix — Party/Raid frames, Nameplates, TomoScore, Chat and Tooltips now handle Midnight's restricted group-role data safely instead of producing secret-value errors.",
    ["wn_360_mythiccombat"] = "Fix — MythicHub and TomoScore commands now wait until combat ends before opening or refreshing protected controls, then continue automatically.",
    ["wn_360_profiles"] = "Fix — Profile Import/Export popups now handle Escape safely in combat without causing blocked keyboard-input actions.",
    ["wn_360_validation"] = "Tested — Standard bars, Human/Cat/Bear paging, Stance, Pet, Possession, special buttons, mouse/keyboard input and combat were validated in game with no new ActionBar taint errors.",
    -- =====================
    -- 3.5.9 — What's New
    -- =====================
    ["wn_359_visibility"] = "New — Action bars now have a Secure Visibility Engine with combat-safe rules for combat state, group type, instances, mounts, targets, hidden mode and custom secure conditions.",
    ["wn_359_gcd"] = "Changed — GCD swipes stay visible where they belong, but pure GCDs no longer show noisy fractional countdown text; numeric text is reserved for the action’s real cooldown.",
    ["wn_359_editmode"] = "Fix — Blizzard Edit Mode now opens without the protected TargetUnit/FocusUnit errors or Compact Party Frame secret-value failures that could previously be attributed to TomoMod.",
    ["wn_359_dormancy"] = "New — Securely hidden bars now go dormant and stop doing unnecessary visual work. Keybinds remain active, and the bar performs a full refresh the instant it becomes visible again.",
    ["wn_359_nativeglow"] = "New — TomoMod now uses its own native glow engine instead of LibCustomGlow, removing the obsolete AnimateTexCoords crash path and centralizing proc animation work.",
    ["wn_359_conditional"] = "Fix — Conditional abilities such as Monk Touch of Death now refresh usability and proc state from Blizzard’s action notifications. Unusable abilities stay dimmed instead of being incorrectly overridden by red range coloring.",
    ["wn_359_specialbars"] = "Fix — Blizzard Pet, Stance and Possess bars stay fully Blizzard-owned for taint safety but are filtered with the 12.1 alwaysBlocked roleset, preventing duplicate native bars without bringing the Edit Mode errors back.",
    ["wn_359_paging"] = "New — Secure Paging for Action Bar 1 adds Alt/Shift/Ctrl pages, Friendly/Hostile Target pages, optional form paging and optional Skyriding paging, all configurable from TomoMod_Options.",
    ["wn_359_priority"] = "Changed — Paging priority now keeps Vehicle/Override/Possess authoritative while manual and modifier pages take precedence over automatic form or Skyriding pages when appropriate.",
    ["wn_359_formsafe"] = "Fix — Druid form changes in combat are now clean and reliable, without protected-action or secret cooldown errors when moving between Human, Cat and Bear.",
    ["wn_359_zoneability"] = "Fix — Zone Ability buttons now keep their icon, GCD and charge display in sync, update correctly when a quest changes state, and disappear when the ability is no longer available.",
    ["wn_359_extragcd"] = "Fix — Extra Action buttons now mirror their GCD and charge recovery on the TomoMod skin without reading or modifying Blizzard's native cooldown widget.",
    ["wn_359_specialbuttons"] = "Changed — Extra Action, Zone Ability and Leave Vehicle keep Blizzard's secure gameplay behavior while TomoMod provides the visible controls, preserving quest, vehicle and taxi behavior.",
    ["wn_359_specialskin"] = "Changed — Extra Action, Zone Ability and Leave Vehicle now use the same action-button skin pipeline as the rest of the bars; invisible Blizzard hitboxes no longer steal clicks or tooltips.",
    ["wn_359_validation"] = "Tested — Forms, special ability buttons, mouse clicks, GCD/charges, visibility, native glows, Edit Mode and secure paging were validated in game without new ActionBar taint errors.",

    -- =====================
    -- 3.5.8 — What's New
    -- =====================
    ["wn_358_input"] = "Fix — Action bar input is now consistently immediate: interrupts, instant abilities, GCD/off-GCD actions, rapid key spam and Shift/Ctrl binds no longer inherit the delayed keybind behavior seen before this update.",
    ["wn_358_state"] = "Fix — Moving, replacing or clearing an action, changing specialization or talents, paging, forms, vehicles and skyriding now refresh the affected buttons cleanly without stale icons, cooldowns, glows, grey states or charge counts.",
    ["wn_358_range"] = "Changed — Midnight 12.1 range coloring now uses Blizzard’s native action-range notifications, while mana/usability updates are event-driven. The old periodic scan is kept only as a compatibility fallback.",
    ["wn_358_glowflyout"] = "Fix — Proc glows now follow transformed/base spell relationships more reliably, stale glows are cleaned up, and flyouts opened from mouseover-faded bars stay visible and return to normal fading when closed.",
    ["wn_358_taintstate"] = "Internal — Custom bookkeeping that used to live directly on Blizzard-owned frames has moved into external weak tables, reducing the amount of addon state attached to protected UI objects.",
    ["wn_358_registry"] = "Fix — TomoMod action buttons are isolated from Blizzard’s native action-button registries and broadcasters where needed, preventing the game’s controller from running retired native buttons through tainted update paths.",
    ["wn_358_secretcooldown"] = "Fix — Combat could flood the error log when Blizzard tried to apply unreadable secret cooldown values to retired native action buttons. Those broadcaster paths are now isolated and no longer generate the repeated cooldown errors.",
    ["wn_358_stancepossess"] = "Fix — StanceBar and PossessActionBar are now left fully under Blizzard’s control. This removes the protected MainActionBar error that could be reproduced by summoning a temporary Monk companion during combat.",
    ["wn_358_blizzbars"] = "Fix — Blizzard’s standard action bars are hidden again through the safe 12.1 visual-suppression path, leaving only TomoMod’s bars visible without reintroducing the controller taint.",
    ["wn_358_validation"] = "Tested — The rebuilt action-bar path has been validated through intensive combat, reloads, talents/spec changes, forms, vehicles, skyriding, transforming spells, charges, flyouts, proc glows and the Monk companion transition with no ActionBar errors observed.",


    -- =====================
    -- 3.5.7 — What's New
    -- =====================
    ["wn_357_talkingheadfix"] = "Fix — Hide Talking Head could leave a talking head's voiceover playing underneath a hidden frame. Talking head frames manage their own visibility, so simply hiding the frame on show left the playing state and its finish timer running — and skipped every line after the first in a multi-line talking head, since the frame was already visible for those. TomoMod now hooks the actual play function and closes each talking head the same way Blizzard itself does, which reliably stops the timer and the voiceover together.",
    ["wn_357_talkingheadcleanup"] = "Internal — A stop-sound call issued in the very same moment a voiceover starts is occasionally ignored by the sound engine, so Hide Talking Head now follows up a fraction of a second later to make sure it actually stops.",
    ["wn_357_queueeyedb"] = "Fix — The queue status eye's position never actually saved. Its entry was missing from the settings defaults table, so the save handler silently skipped writing a new position every time you dragged it — the eye moved fine on screen, but forgot where you put it on the next login. The missing entry is back, and the save path now creates it on the fly if your saved settings are still missing it, so an out-of-date save costs nothing worse than one extra table.",
    ["wn_357_queueeyeposition"] = "Fix — The queue status eye's default position was a blind guess that landed in a different spot on every resolution — off-screen entirely on an ultrawide monitor, which is how this was caught. It now defaults to a spot beside the minimap, where the eye actually lives.",
    ["wn_357_lfgeyesurvive"] = "New — The Group Finder eye used to disappear entirely when you hid the Blizzard micro menu, since it lives inside that same menu's container. It now stays put — Group Finder queue status is always visible, wherever you've placed it, whether the native micro menu is hidden or not.",
    ["wn_357_lfgeyeoptions"] = "New — Two new Micro Bar options let you turn the Group Finder eye off entirely or resize it, next to the setting that hides the Blizzard micro menu.",
    ["wn_357_lfgeyescale"] = "Fix — The Group Finder eye's size slider did nothing unless Micro Bar was fully enabled with \"hide the Blizzard micro menu\" also turned on — the scale was silently reset back to normal on every refresh otherwise. It now applies regardless.",
    ["wn_357_roletaintguard"] = "Fix — A nameplate error could still slip through comparing a role you're not allowed to read directly, even with the existing guard in place. That comparison is now double-checked, so an unreadable role is treated as no role instead of raising an error.",
    ["wn_357_cooldowntaint"] = "Fix — Some action bar buttons could spam an error updating their cooldown swipe when the game wouldn't let the value be read directly, even on bars with skinning turned off. That update is now skipped safely on every affected button and every cooldown it carries, instead of raising an error.",
    ["wn_357_mainbartaint"] = "Fix — A rare error could appear trying to reshow the default action bar after mounting or entering a vehicle. It is now silenced the same way similar cases already are.",
    ["wn_357_mailiconcrash"] = "Fix — The minimap's mail icon could raise an error every time you got new mail. It no longer does, and the icon behaves exactly as before.",
    ["wn_357_buggrabber"] = "New — If you also run !BugGrabber, Diagnostics now backs itself up against it, catching errors it saw before TomoMod's own tracking started this session. Nothing changes if you don't have it installed.",
    ["wn_357_shieldenchant"] = "Fix — The character sheet's weapon enchant warning could flag a shield or an off-hand held item (tomes, frills, and the like) as missing an enchant, even though neither can actually take one — tanks with a shield and casters holding an off-hand item saw a red warning for something that was never enchantable to begin with. The warning now only shows on a slot holding a real, enchantable weapon.",
    ["wn_357_inspectiteminfo"] = "New — Inspecting another player now shows the same per-item breakdown as your own character sheet: item level, upgrade track, enchant text (or a missing-enchant warning) and gem sockets next to every equipped item, instead of just one averaged number at the top.",
    ["wn_357_inspectiteminfotoggle"] = "New — A new checkbox lets you turn the Inspect frame's item info/enchants/gems off independently of your character sheet's own settings.",
    ["wn_357_enemybuffgrid"] = "New — The Enemy Buffs tracker on your target and focus frames (the helpful auras cast on whatever you're targeting) now has its own Direction (left/right) and Next Row Goes (up/down) dropdowns, plus an Icons Per Row slider — it was previously fixed at 3 per row, growing upward, with no way to change either. The count slider's ceiling also went from 8 to 12, and any stack is capped at 3 rows, hiding the rest instead of growing forever.",
    ["wn_357_aurasgrid"] = "New — Regular Auras (buffs, debuffs, or both, on player/target/focus) now use the same icons-per-row grid as Enemy Buffs: an Icons Per Row slider (default 6) replaces the old pixel-width wrap, with the same 3-row cap.",
    ["wn_357_auradirectionfix"] = "Fix — Direction settings on both Auras and Enemy Buffs used to silently do nothing: the aura engine's live-refresh only re-applied grow direction when the icon size or count also changed in the same update, and even then a fixed anchor corner meant \"grow upward\" left the icon stack floating a few rows above the health bar instead of sitting flush against it. Both are fixed — direction and per-row changes apply immediately, and the stack now grows from right where it should, with nothing floating.",
    ["wn_357_aurasliverefresh"] = "Fix — Several Auras/Enemy Buffs options (count, direction, type) used to need a `/reload` to actually apply, even though they looked like they should update instantly. Most of them now do; the two that still genuinely need one — Enable and the buff/debuff/both Type dropdown — now say so directly in the panel.",
    ["wn_357_microbarcombatfade"] = "Fix — Hovering a Micro Bar button in combat could raise a blocked-action error instead of just fading the bar in. The hover fade now snaps straight to its target instead of animating while in combat, which avoids the blocked call entirely.",

    -- =====================
    -- 3.5.5 — What's New
    -- =====================
    ["wn_355_barhoverblocked"] = "Fix — Simply moving your mouse over an action bar button during a fight produced a blocked-action error, every single time. Blizzard's own button update runs on mouseover and ends by writing a press-and-hold setting directly — a write that isn't allowed in combat, and that gets blamed on TomoMod because the buttons are ours. One entry per hover is how a single session collected 127 of them. TomoMod now writes that setting from its own secure path, where it was already being written correctly, and skips Blizzard's redundant version.",
    ["wn_355_barpingblocked"] = "Fix — The same mouseover ran a second forbidden write two lines later, this one belonging to the ping system. Pings target Blizzard's own bars and never applied to TomoMod's buttons, so that call is now skipped as well. Neither of these ever broke anything on screen — but they buried real errors under noise and made the addon look responsible for whatever else went wrong in the same fight.",
    ["wn_355_escapekeyblocked"] = "Fix — With a TomoMod window open in combat, every key you pressed produced a blocked-action error — holding a movement key down was enough to fill the error log by itself. The combat check was already there, it just ran one line too late, after the protected call it was meant to prevent. It now runs first.",
    ["wn_355_microportrait"] = "Fix — On the custom micro menu, the character sheet button showed as a blank coloured square while every other button looked right. It is the only one whose art isn't a fixed icon — it's your character's portrait — and TomoMod was copying a texture reference that simply doesn't reproduce anywhere else. It now asks the game to draw your portrait onto the button directly, and borrows the same rounded mask and drop shadow Blizzard uses on its own character button — so it shows your character with the same shape and depth as the buttons beside it, instead of a flat square.",
    ["wn_355_perftooltip"] = "New — The memory tooltip on the custom micro menu now opens with a Performance block: your framerate, your home and world latency, and total addon CPU. The CPU line only means anything when the game is recording it, which is off by default and needs a reload to change — so rather than show you zeroes that look like a real measurement, it says \"profiling disabled\" until you turn it on.",
    ["wn_355_micronative"] = "Fix — On some clients, ticking \"hide the Blizzard micro menu\" did nothing whatsoever: the box stayed ticked, the bar stayed on screen. TomoMod looked for Blizzard's menu under a single name that has moved between patches, and gave up the moment it wasn't there — without even hiding the buttons, which was the part that would have worked. It now recognises every name Blizzard has used and always handles the buttons regardless. If nothing at all answers on your client, it now says so once in chat instead of failing silently — please report it with your client version if you see that message.",
    ["wn_355_queueanchor"] = "New — The queue status eye — the small icon that spins while you're waiting for a dungeon or battleground — can now be moved. Blizzard attaches it to the minimap and gives it no Edit Mode handle, which made it the one HUD element you simply could not place. It now appears among the movable anchors in `/tm sr`, and moving it during combat is applied the moment the fight ends rather than being refused.",
    ["wn_355_escapepropagate"] ="Internal — Keyboard propagation for those windows is now established once when the window is built, rather than re-set on every keypress. It never needed re-setting: it is a persistent property of the frame, and the only thing that ever turns it off is closing the window with Escape, which cannot happen in combat.",

    -- =====================
    -- 3.5.4 — What's New
    -- =====================
    ["wn_354_preyfix"] = "Fix — The Prey Tracker's progress bar was permanently stuck at 0%. `GetPreyWidgetInfo` kept only the boolean returned by `pcall`, not the actual widget data, so reading `.progressPercent` off it threw an error every second and aborted the update before it could ever fall back to the quest's own objective count. The call now keeps both return values, so a missing widget field is handled quietly and the real progress — read from the hunt's own objective count — comes through correctly.",
    ["wn_354_extranudge"] = "Change — The Extra Action Button and Zone Ability move overlays lose the four click-to-nudge arrows that surrounded them in `/tm layout`. Dragging the overlay with the mouse still repositions it exactly as before; only the extra buttons are gone.",
    ["wn_354_perflocale"] = "Internal — Loading a non-English locale used to build and instantly discard nearly 2900 translation table entries, five times over, on every `/reload` — the file compiled fully before the addon could decide it wasn't needed. Each non-active locale file now bails out before building its table, and the base-locale merge check (which was silently a no-op due to a metatable quirk) is fixed to only test what it's supposed to.",
    ["wn_354_perfrangeticker"] = "Change — The party and raid frame range-check ticker, a safety net for cases the game's own range event doesn't cover, was running twice a second per frame regardless of group size. It now runs every two seconds — still faster than any transition it needs to catch — cutting that cost by three-quarters.",
    ["wn_354_perfaura"] = "Internal — Scanning a unit's defensive auras opened a new protected call for every buff checked, up to forty times per aura update per tracked unit. It's now one protected call around the whole scan, with identical fallback behavior if something goes wrong partway through.",
    ["wn_354_perfpartylookup"] = "Internal — Party frames dropped a linear frame search in favor of a direct lookup table, and now fully unsubscribe from health/power/aura events while in a raid — where those frames are hidden and the raid frames handle updates instead — rather than quietly continuing to process events for nothing.",
    ["wn_354_perfcdf"] = "Internal — Cooldown Forge's update event could fire several times in the same frame during a burst of cooldown changes, each one repainting every bar and icon on its own. Those bursts are now collapsed into a single repaint per frame.",
    ["wn_354_perfmisc"] = "Internal — A handful of smaller hot-path cleanups: boss frame polling no longer builds new strings every tick, the Objective Tracker's deferred layout pass and recursive content scan no longer allocate throwaway tables on every node, and Skyriding's speed calculations no longer rebuild a closure on every tick.",
    ["wn_354_optionslod"] = "Change — The options panel — Config, 28 files and roughly 17,900 lines — now loads on demand instead of at login. It moved into its own TomoMod_Options add-on and only loads the first time you actually open it; every button and slash command that used to reach it directly now loads it transparently on first use.",
    ["wn_354_optionsfallback"] = "Internal — Mythic+ score colors, previously read once at login from a theme table that now lives in the on-demand options add-on (and so didn't exist yet), are read lazily instead — they resolve correctly the moment the options panel has been opened once, rather than being frozen at an empty fallback for the whole session.",
    ["wn_354_escapefix"] = "Fix — The Damage Meter's Death Recap, Run Recap, Spell Breakdown and Target Breakdown windows could leave Escape unable to close the game menu after being used, because closing them the old way routed through a function whose protected calls get refused once tainted. They now use the same safe close-on-Escape handler as every other TomoMod window.",

    -- =====================
    -- 3.5.3 — What's New
    -- =====================
    ["wn_353_brezvisual"] = "Enhancement — The Battle Rez Counter HUD received a visual refresh inspired by Tui's design patterns. The frame now features a professional multi-layer backdrop with inner shadow effects, improved spacing, and refined typography for better readability during combat.",
    ["wn_353_brezglow"] = "New — An optional glow effect now activates when battle resurrections are available, providing improved visual feedback and making the counter more noticeable at a glance.",
    ["wn_353_brezcolors"] = "Change — The Battle Rez Counter's color palette has been upgraded with Tui-inspired teal accent colors and better contrast between active (green) and cooldown (red) states for clearer status indication.",
    ["wn_353_brezlayers"] = "Internal — The Battle Rez Counter frame layout was refactored with proper layer ordering: background, inner shadow, icon texture, cooldown swipe, and text overlays. Better geometry and positioning across all UI elements.",
    ["wn_353_preytracker"] = "New — Prey Tracker: A movable progress bar displaying active Prey hunt progress (Midnight expansion feature only). Shows the hunt name, difficulty level, and real-time progress percentage with a smooth visual design matching the Battle Rez Counter.",
    ["wn_353_preyconfig"] = "New — The Prey Tracker is disabled by default (Midnight-only content) and can be enabled in Config → QOL → Combat → Prey Tracker. It automatically hides when no Prey hunt is active and shows a preview during placement mode.",
    ["wn_353_preylayout"] = "New — The Prey Tracker is fully integrated with TomoMod's unified layout mover system. Drag to position it alongside other HUD elements using `/tm layout`, with synchronized lock/unlock behavior and consistent placement mode previews.",
    ["wn_353_preyapi"] = "Internal — The Prey Tracker reads C_QuestLog and C_UIWidgetManager APIs to detect active Prey quests and track progress in real-time with a 1-second update rate, providing accurate status information during hunts.",
    ["wn_353_brezcrash"] = "Fix — The Battle Rez Counter could fail to load entirely on some client builds: a cooldown method that no longer exists, and a frame-level call made on a texture instead of a frame, both crashed module init. Both are fixed, along with a glow effect that crashed the moment it needed to reappear after being hidden once.",
    ["wn_353_preyevent"] = "Fix — The Prey Tracker registered an event that doesn't exist on this client, throwing during init. Fixed, and every event registration is now guarded so a missing event can no longer crash the module.",
    ["wn_353_preygui"] = "New — The Prey Tracker now has an actual settings section: Config → QOL → Automations, with an enable checkbox and width/font-size sliders. It previously had no in-game way to turn on.",
    ["wn_353_abmover"] = "Fix — The \"Action Bars\" entry in `/tm layout` did nothing at all. The ported action bar code runs in a sandboxed environment that never exposed itself to the rest of TomoMod, so move mode silently failed to activate. It now reaches the bars correctly.",
    ["wn_353_abflash"] = "Fix — Pressing an action button turned its icon fully white, and the first attempt at fixing it earlier in this same release did not work. The texture involved is not a cutout shape that needed a different blending mode, it is a solid white square — so blending it differently still painted it over the icon, and the change made three other textures that had been fine all along come out brighter than they should. The press effect now darkens the icon instead of covering it, which is what it was always meant to do.",
    ["wn_353_abpressopt"] = "New — You can choose what a button does while you hold it down. Config → Action Bars → General has a Press effect setting with three choices: Blizzard's own flash, which is now the default, TomoMod's darkening, or nothing at all. It takes effect the moment you pick it, with no reload.",
    ["wn_353_abposition"] = "Fix — A dragged action bar reset to its default position on every `/reload`. The saved position was never actually being written, and the restore path never read it back even when it was. Both are fixed — bar positions now persist correctly.",
    ["wn_353_abcolor"] = "Change — The move-mode overlay for action bars and the extra action/zone ability buttons now uses TomoMod's teal brand color instead of Tui's original blue, matching every other `/tm layout` overlay.",
    ["wn_353_abextramover"] = "Fix — The Extra Action Button and Zone Ability holders had their own separate move overlay that was never connected to `/tm layout` — always visible on screen but impossible to drag from the unified layout tool. Both now have a proper \"Extra Button\" entry in `/tm layout`.",
    ["wn_353_brezicon"] = "Fix — The Battle Rez Counter's icon rendered as a solid black square: the texture path used for it doesn't exist on this client. It now shows the correct Rebirth icon.",
    ["wn_353_nameplaterole"] = "Fix — Nameplates could spam taint errors when reading a unit's group role in restricted content, because the role can come back as a secret value that can't be compared directly. It's now guarded and treated as unknown rather than thrown.",
    ["wn_353_abmicrodefer"] = "Fix — The micro menu buttons could go missing for the rest of a session. When they need to be moved back into place and a fight is running, the move waits for combat to end — but the part meant to wake it up afterwards was never there, so it waited forever, silently, with nothing in the error log to say so. It now runs the moment you leave combat.",
    ["wn_353_abpaging"] = "Fix — When the bar changed under you — a vehicle, a possess bar, a stance, a skyriding page — the buttons kept the artwork of the page you had just left, or showed nothing at all, and only a full rebuild or a /reload put them right. The repaint meant to follow a page change was hanging off a Blizzard function that no longer exists on the current client, so it never ran once. The bars now repaint themselves when they change pages.",
    ["wn_353_aboverride"] = "Fix — The override bar was never listened to at all. That is the bar a vehicle, a skyriding mount or a druid's Flight Form puts you on, and because nothing told the bars it had happened, they carried on showing the actions of the page you were on before. It is now watched like any other page change: the slots are re-read and the buttons repainted.",
    ["wn_353_totembar"] = "New — A totem bar. It shows the totems you have out, in your class's own priority order, each icon carrying the time it has left and a sweep running down it. Right-click one to dismiss that totem, and the bar takes itself off screen when nothing is out. Blizzard's own totem frame stands down while it is on and is handed back intact the moment you switch it off.",
    ["wn_353_totemconfig"] = "New — The totem bar is switched on in Config → Action Bars → General, under Totems, and takes effect straight away with no reload. It is off by default. Icon size, spacing, border, zoom, which way it grows, and the look of the duration text and the sweep are all yours to set.",
    ["wn_353_totemlayout"] = "New — Position it from `/tm layout` like every other HUD element. It stays visible and labelled there even when you have no totems out, so you can place it before ever casting one instead of having to drop a totem, run to the layout tool and hope it is still up.",
    ["wn_353_petstancelayout"] = "New — The pet bar and the stance bar can be laid out at last. They had the orientation, button count and column controls kept from them on the belief that the game owned their shape — it does not: they run through exactly the same layout code as the eight main bars, and always did, so the settings were live all along with nothing on screen to reach them. All three controls are now there for both, capped at ten slots rather than twelve. Setting the stance bar higher than the number of forms your class has is harmless; it is clamped for you.",
    ["wn_353_loots17"] = "New — The loot tables are up to date for Season 17. The dungeon rotation has turned over completely, so all eight of the new dungeons are there — Kings' Rest, Temple of Sethraliss, Ruby Life Pools, The Blinding Vale, Void Scar Arena, Nalorakk's Lair, Murder Row and Altar of the Fangs — along with the two new raids, Tidebound Grotto and Venomous Abyss, and the class restrictions for every item they drop. Last season's tables are retired rather than kept alongside: nothing in either rotation points at them any more.",
    ["wn_353_mplusteleports"] = "New — The Mythic+ tracker knows the teleports for the new rotation. The five rotation dungeons arrive with their teleport spells, and Kings' Rest and the Temple of Sethraliss have theirs filled in at last — both were sitting empty in a rotation they are part of, so the tracker had nothing to offer for either.",
    ["wn_353_keysync"] = "Fix — `/tmt keysync` now does something. The key-sync diagnostic had been written, and the note above it even named the command it was meant to answer to, but nothing in the handler ever routed there — so the one tool for telling a sync that is quietly failing apart from one that simply found nothing to match could not be reached from the game at all. It is now listed in `/tmt help` in all six languages.",
    ["wn_353_totemport"] = "Internal — The totem bar is a port rather than a rewrite, carried across from Tui as written with every changed line marked, so catching up with the original later is a replay of a handful of marks instead of a second reading of the whole file. Its cooldowns refuse secret values outright rather than guessing at them, which is how the rest of the ported code already treats restricted content, and every secure write waits for the end of a fight instead of being attempted mid-combat.",
    ["wn_353_abemptyslot"] = "Fix — And with \"hide empty slots\" turned on, those same swaps left the bar blank rather than stale: the buttons were there but invisible, and unticking the option made the problem vanish, which is what gave it away. The repaint was running one frame too early, while the buttons still pointed at the slots of the page you had left, so every one of them was judged empty and faded out — with nothing running afterwards to think again. It now runs a second time on the next frame, once the buttons have caught up.",

    -- =====================
    -- 3.5.2 — What's New
    -- =====================
    ["wn_352_icons"] = "Fix — The action bar icons came back black. The check meant to spot an empty slot was looking for the icon to be given as a file path, which is how the game used to answer and has not for years — it now hands back a number instead. So every real icon failed a test written to catch the ones that were missing, was wiped, and left an empty square where your spell had been. Both the usual route and the fallback now accept either answer.",
    ["wn_352_tint"] = "Fix — Out of range, out of mana and unusable stopped showing after a reload or a bar change, and moving the mouse over the button would bring them back. TomoMod was tinting the icon in the very same place Blizzard tints it, so whichever of the two ran last decided what you saw. The tint is now a layer of TomoMod's own laid over the icon, which shades it exactly as before without the two of them writing over each other — and when there is nothing to signal, it simply is not there.",
    ["wn_352_scope"] = "Fix — With the action bars turned off, the skin kept skinning anyway. It falls back to finding buttons by name, and those names belong to Blizzard's buttons whether or not TomoMod has taken them over — so switching the bars off left the skin repainting frames it had no business touching. It now checks that the bars are actually running before it changes anything.",
    ["wn_352_move"] = "Internal — The action bars have moved house. They were filed away with the quality-of-life tweaks because that is where the skin began, and they stopped being a tweak the moment the last release turned them into a system of their own with an engine, five layers and their own buttons. They now sit with the unit, party and raid frames, where they belong, and are loaded the way those are. Nothing about them changed on the way over — the three fixes above came with them.",
    ["wn_352_tui"] = "Internal — Groundwork, and nothing you can see yet. Some of what is planned for the bars exists already in another addon, and rewriting it line by line to fit here would be slow and would introduce mistakes that are not in the original. So there is now a thin layer whose only job is to let one of those files run here untouched. Where TomoMod already has its own version of something — anchoring, move mode — the layer points at that instead of dragging a second copy along, which is why four functions stand in for sixteen hundred lines of it. Nothing calls any of this yet; it is deliberately being put in place on its own, before anything relies on it.",
    ["wn_352_port"] = "Internal — And then the thing that layer was built for. The action bar module from that other addon is now here in full: fourteen files, a little over eight thousand lines, brought across as they were written rather than retyped to fit. Every place a line had to change is marked, so that when the original moves on, catching up means replaying a handful of marks instead of reading the whole thing again and hoping to notice what moved. It is loaded, it is checked, and it is switched off on purpose — landing something this size and turning it on in the same release is how you end up unable to say which of the two broke your bars.",
    ["wn_352_portlayers"] = "Internal — What is inside it, for when the switch is thrown. Flyouts first: the last release shipped TomoMod's own buttons and had to say plainly that a mage portal or a hunter trap would not open on a bar using them, because the game refuses the ordinary route on a button an addon made and the way around it is a few hundred lines nobody writes twice. Those lines came with the port, along with a matching restyle of the game's own flyout for the buttons that are still Blizzard's. The extra action button and the zone ability get a place of their own to sit, one the game cannot quietly move them out of. Cooldowns, the glow and the greying-out of what you cannot cast each arrive as their own layer. None of it is on yet.",
    ["wn_352_switch"] = "Change — The switch is thrown: the action bars now run on the ported module, and the system that drove them before it has been removed rather than left sitting there switched off, because two of them each convinced they own the same buttons is not a state worth shipping in order to find out how it goes. The last three pieces came with it — the skinning, which strips the game's own artwork off a button and draws it from scratch, down to the macro name and the stack count; fading a bar out until you put the mouse on it, one bar at a time, with the bar held visible while your spellbook is open; and the overlays you see when you go to move a bar. Masque is supported now too, if you use it, and simply absent if you do not.",
    ["wn_352_bindings"] = "Change — Your keys carry over, and there are 106 fewer things to bind. The previous release shipped a binding for every button on every bar, so putting TomoMod's own buttons on a bar meant binding it a second time in the game's keybinding window, under a TomoMod heading, next to the binding you already had. The new buttons do not ask for that: they read whatever you have bound to the game's own action bar keys and take those over for themselves. A bar you had set up keeps working without you touching anything, and a key already spoken for by something else is left exactly where it is.",
    ["wn_352_settings"] = "Change — The Action Bars options page is back, and there is one thing to know before you update. When the bars were switched over earlier in this same release the page was reduced to a single message, because every control on it wrote to a system that no longer existed. It has now been rebuilt against what the bars actually read: five tabs — the buttons themselves, the text written on them, the indicators for out of range and out of power and what you cannot cast, fading a bar out until you point at it, and one tab per bar for how many buttons it carries and which way it grows. The thing to know: your old bar settings do not come across. The old way of storing them and the new one do not name anything the same, and the few names that look alike do not mean the same thing, so carrying them over would have meant guessing — and a wrong guess hands you a layout you never picked and cannot work back to. The old settings are cleared once, on your first login after the update, and the bars come up on clean defaults for you to set as you like.",
    ["wn_352_chatcopy"] = "New — Copying text out of the chat was rebuilt. The window you get now looks like the rest of the chat rather than a plain grey box: the text is already selected and scrolled to the last line the moment it opens, you can resize it, and it holds 500 lines where it used to stop at 128. There is a copy button on the chat window itself as well — always visible, only when you point at the chat, or not at all, whichever you prefer, under Skins, Chat Frame. And the little window that asks you to copy a link's address now matches everything else instead of being the game's own dialog.",

    -- =====================
    -- 3.5.1 — What's New
    -- =====================
    ["wn_351_engine"] = "Internal — The action bars used to be repainted five times a second, every button, whether or not anything had changed. That was the shape a skin ends up with when it grows into a feature set without ever being given somewhere to keep track of things. There is now one piece that owns the question — what state is this button in — and it is told by the game when something happens instead of checking on a timer, and it passes the news on only when a value has actually changed. Range is the one exception, because the game has no way of announcing it; that check still runs on a timer, and only while you have a target. It also never assumes the button underneath belongs to Blizzard, which is what made everything else in this release possible.",
    ["wn_351_render"] = "New — Icons and cooldowns became yours to set. The cooldown numbers and their size, the colour and opacity of the sweep, the edge and the shine, the charge and stack text and its size, the macro name, greying out an action you cannot use, and how much the icon is cropped — down to not cropped at all. There is also a choice of who draws the cooldown: Blizzard, which keeps its own sweep and simply restyles it, or TomoMod, which draws it. Blizzard is the default and stays the safer of the two for now; TomoMod's is what the new buttons further down need, and it is there so it can be proven before anything relies on it.",
    ["wn_351_glow"] = "New — Two glows on the bars, and they can both be lit at once. One is the classic proc highlight; the other follows the rotation suggestion the game itself makes. Each has its own style — Pixel, Autocast, Button, Proc or Blizzard — its own colour, and for the pixel one the number of lines, their thickness and the animation speed. They coexist rather than taking turns, because each keeps its own hold on the button. Matching is done on the spell, so a macro that ends up casting something glows exactly as the spell would on its own, and a talent that renames a spell is followed too. The rotation glow is off by default and needs the feature to exist on your character.",
    ["wn_351_hotkeys"] = "New — The keybind text on the buttons is now yours: show or hide it, its size, its colour, which corner it sits in, how far it is nudged, whether it is shortened, and whether it appears at all on an empty slot. It is worked out from the binding itself rather than copied off Blizzard's label, which matters because a button TomoMod makes has no such label to copy — Blizzard's is kept as a fallback so an unexpected change in a future patch means slightly worse text rather than none. There is also a binding mode: turn it on, hover a button, press a key. Right-click or Escape clears one. It will not open in combat.",
    ["wn_351_special"] = "New — Things the bars knew and never showed you. On a skinned bar you could not see which stance you were in, which weapon enchant was equipped, or which pet ability was set to cast itself: the skin removes Blizzard's markers and washes out its highlight. There is now a ring for the active action and for equipped items, each with its own colour and a shared thickness, on one ring with an order of precedence so two of them never pile up into a mess. Pet autocast gets its own shine that sits alongside the two glows above. The pet bar can hide itself when you have no pet. Stances have no equivalent — there is no way to ask the game whether a class has forms at all, and Blizzard's own stance buttons already vanish when there is nothing to show.",
    ["wn_351_ownbuttons"] = "New — TomoMod can now make its own action buttons instead of borrowing Blizzard's. It is off everywhere, switched on one bar at a time, and undone by unticking it and reloading. Everything above works on them unchanged. Please read the limits before turning it on, because they are real: flyouts do not open on a converted bar — mage portals, hunter traps, summoned flasks. Vehicle and override bars still follow the page change, but the special exit button and its artwork do not come with it. The game's rotation highlight is not drawn on them; use the rotation glow above instead. Pet and stance bars are left on Blizzard's buttons entirely. It is marked experimental because it is.",
    ["wn_351_bindings"] = "New — The new buttons come with 106 bindings already declared, so they show up in the game's own keybinding window under a TomoMod heading with a section per bar. They are bound through a dedicated click rather than a plain left click, which is what makes casting on key press behave correctly — this is a known corner, and Bartender4 moved the same way years ago for the same reason.",
    ["wn_351_keybound"] = "New — TomoMod's bars join the shared binding mode that Dominos, Bartender4 and Bagnon use, so one pass binds your bars and theirs together instead of every addon insisting on its own. The library that arbitrates this is now included, so the shared mode is there whether or not you run one of those addons. One detail worth recording for whoever updates it next: it must be taken from a packaged release, never from its GitHub mirror, which computes its own version from a marker that only ever gets filled in inside a source checkout — copied anywhere else it fails as soon as it loads.",
    ["wn_351_tabs"] = "Change — The Action Bars options page is five tabs now instead of two: Skin, Buttons, Glow, Hotkeys and Bars. Everything new used to land in one long column on the skin tab, and three of this release's five layers would have gone there too.",

    -- =====================
    -- 3.4.6 — What's New
    -- =====================

    ["wn_346_probe_secret"] = "Fix — The buff icons in the Cooldown Studio, which 3.4.5 had just taught to keep their countdown in combat, threw an error on the first icon that watched a buff. The invisible marker attached to each icon was asked whether it was on screen, on the understanding that this is a question about a piece of the interface rather than about the buff — and it is not. Whether an aura icon is on screen is whether the buff is up, which is precisely what the game is withholding, so the yes-or-no that came back was itself withheld, and asking it the question was what failed. Protecting the call could never have helped: the call worked fine, and the failure came a line later, from looking at the answer.",
    ["wn_346_probe_cooldown"] = "Change — So the question is put to something else. Each icon already has its own sweep, the one the game drives directly, and that piece belongs to TomoMod rather than to the game: the sweep appears while the buff is up and goes away when it ends, and nothing stops the addon from reading that. It gives the same answer from the side of the line where reading is still allowed. The game's own marker is kept behind it as a second opinion, now asked safely, and if neither will answer the icon simply contributes nothing that frame and carries on driving the sweep — which was always the larger half of what it is there for.",

    -- =====================
    -- 3.4.5 — What's New
    -- =====================

    ["wn_345_class_secret"] = "Fix — Health bars threw an error on every update for any player whose class the game now hides, 399 times in a single session in the report that led to this. Patch 12.1 widened what an addon is not allowed to read, and a hidden value is not simply missing: it is live, and it fails the instant anything is done with it — comparing it, looking something up with it, joining it to a piece of text, or even asking whether it is true. So the check has to come first; there is no catching it afterwards. Sixteen places in TomoMod each read a unit's class and looked the colour up the same way, and they now all go through one set of helpers that asks whether a value can be read before touching it. Each place decides for itself what an unknown class means, because the right answer is not the same everywhere: the class reminder assumes someone might need the buff rather than skipping them, the caster tint on hostile nameplates is left off rather than guessed, and the keystone list and TomoScore simply draw without a colour. The group leader crown is in the same family — whether someone leads the group can also be hidden now, and when it is the crown stays hidden, since showing one on a player who may not be the leader is worse than showing none.",
    ["wn_345_class_passthrough"] = "New — And then the class colours came back. Falling back to a faction colour when the class cannot be read is correct, but in a dungeon that is every single person in the group, so the frames would have been the wrong colour permanently rather than now and then. It turns out the game will still colour a unit for you even when it will not tell you the class: the class goes into one of the game's own functions and the colour comes straight back out of another, into the bar, without the addon ever reading either. Health bars on unit frames, nameplates, party frames and raid frames use that route first and keep their class colours. It only works where the colour goes straight onto something, though — anything that needs to darken or blend it has to read the numbers, and there the faction colour is still the answer.",
    ["wn_345_nameplate_auras"] = "Fix — Enemy nameplates disappeared when you turned the camera. Not the auras on them: the whole plate. Reading a unit's auras is another thing patch 12.1 can now refuse, and the refusal came from the middle of drawing the plate, so everything after it — the health bar, the name, the cast bar — simply never happened, and the plate looked deleted. Turning the camera set it off because that is what brings new plates into view. Every aura read on a nameplate is now guarded on its own, so a refusal costs that one aura its icon or its countdown and nothing else. Two of the guards written for this turned out to protect nothing at all, for a reason worth knowing if you write Lua: a guard placed around a call does not cover another call passed to it as an argument, because the argument runs first. One of the two sat around the exact call that was throwing.",
    ["wn_345_aura_probe"] = "Internal — Eleven different parts of TomoMod scan a unit's auras — the auras on your frames and on nameplates, the dispel highlight, the HoT row, the group buff icon, the defensive icons, CooldownForge's buff tracking. Each one used to walk up to forty aura slots one at a time, guarding every single step, and find out only at the end that the game was not going to answer at all. They now ask once, and the answer is remembered for the rest of that frame, so forty group frames cost one question instead of sixteen hundred guarded steps. The question is deliberately asked through the most permissive way of reading an aura, so an answer of no means every other route was already shut and nothing that could have been drawn is being skipped. One real bug came out of it: CooldownForge was emptying its own list of tracked buffs whenever a rescan was refused, and then tracking nothing at all until the game allowed a read again. Worth being plain about the limit — this makes things cheaper, not more complete. An icon whose scan cannot read anything still goes dark, exactly as it did before.",
    ["wn_345_aura_engine"] = "New — Auras were missing for most of a pull, and nothing said so: no error, nothing on the plate or the frame, just an empty space where the thing you wanted to see should have been. Everything else in this release makes a refused aura read harmless; none of it makes the aura come back, because the game will not hand it over while a fight is running. So TomoMod stops asking. It now describes what it wants — these auras, this many, laid out like this, styled like this — and the game does the looking and the sorting itself and hands back the finished icons. Nothing on TomoMod's side reads an aura any more, so there is nothing left to refuse. Every aura row in the addon works this way now: nameplate debuffs and buffs, the auras and target buffs on your frames, party heal-over-time icons, raid debuffs and raid heal-over-times. The heal-over-time rows needed one extra step, because they worked by recognising particular spells and the spell is exactly what is withheld — so the list of spells to watch is handed to the game up front, and it does the picking. The dispel cue took the longest to work out and changes shape as a result. It used to be a coloured border around a player's frame, lit by checking each harmful effect against what you can remove — and since neither of those can be looked at any more, it only ever lit up when you were out of combat, which is the opposite of when a healer needs it. It is now a small icon in the corner of the frame, and the game itself picks which effect to show: there is a way to ask it directly whether you can dispel something, and it answers without letting anyone read anything. Two things to know about it: bleeds never appear, because no class ability removes one, and crowd control is left out on purpose since it has its own display. Four bugs were caught along the way — an error every time a nameplate went away, icons created mid-fight that came out with no size and stayed invisible for good, switches for showing debuffs or heal-over-times that stopped taking effect until a reload, and a size slider that had quietly stopped controlling anything.",
    ["wn_345_aura_layout"] = "Fix — Aura rows stopped wrapping and always grew the same way, whatever the settings said. Handing the display over to the game meant telling it how big one icon is, and that turned out not to include which way the row should run or where it should wrap — those belong to the row itself, and were simply never passed on. Both directions work again, horizontal and vertical independently, along with the spacing between icons. Related: a row set to show eight auras could draw sixteen when it was showing both buffs and debuffs, since those are two separate lists and each was given the full allowance. The allowance is shared now. The flip side is that a row of eight can no longer be filled entirely by debuffs when there are no buffs to show — the two lists cannot lend each other room.",
    ["wn_345_cdf_probe"] = "New — Buff icons in the Cooldown Studio keep their countdown in combat. The studio is the one display that cannot be handed to the game wholesale: it puts cooldowns and buffs in the same row, which the game has no concept of, and what it really needs is narrower anyway — is this buff up, and how long is left — which is exactly what it is no longer allowed to look at. So it asks without letting the game draw: an invisible marker is attached to each icon, watching only that one buff, and the game drives the icon's own sweep directly. Whether the buff is up is answered by asking that marker whether it is on screen, which is a question about a piece of the interface rather than about the buff. One consequence worth knowing: only one thing is allowed to write the sweep at a time, because two of them taking turns is what made it flicker.",
    ["wn_345_dm_dropdowns"] = "Fix — On the Damage Meter options page, the theme and bar texture dropdowns opened with the right number of rows and nothing written on any of them. The meter labels its lists one way and TomoMod's dropdown expects another, and unlike the other controls that one has no fallback, so every row was drawn blank. The Damage Meter page also has its own icon in the menu now — it had been sharing the Diagnostics one, so two entries carried the same picture.",

    -- =====================
    -- 3.4.4 — What's New
    -- =====================

    ["wn_344_damagemeter"] = "New — TomoMod now has a damage meter. DPS and HPS, damage taken, avoidable damage, enemy damage, absorbs, interrupts, dispels and deaths, sorted into Damage, Healing and Actions that you cycle from the header, with a Current and an Overall session and a combat timer. Worth knowing how it works, because it explains what it can and cannot do: it reads Blizzard's own combat data rather than listening to the combat log and adding everything up itself. That means no wall of events to sift through, and numbers that match Blizzard's own meter because they are the same numbers. A client without that data says so plainly instead of showing you an empty window. It answers to /tdm, and can report to say, party, raid, guild, instance, a whisper, whichever channel fits your group, or just to yourself.",
    ["wn_344_dm_windows"] = "New — Up to five meter windows at once, each with its own type, session, columns and number format: watching damage and healing side by side is the ordinary case, and one window meant cycling back and forth all fight. Drag one against another and they dock edge to edge — from then on they move together and share the edge they meet on, so resizing one resizes the other, and pulling a window away unhooks it again. Nine looks come with it — Tomo Dark, Tomo Neon, Minimal, Glossy, Ember, Frost, Terminal, Void and Parchment — along with the bar texture, the font and its size, the bar height, the accent colour or class colours, how transparent the window is in and out of combat, and an option to keep your own bar pinned in view.",
    ["wn_344_dm_breakdowns"] = "New — A number on a bar does not tell you what produced it. Left-click any bar to open its spells inline, right-click to give them their own window: totals, hits, crits and crit rate per spell. A target breakdown answers the other half — not what you cast, but what you cast it into — and each pull can be read on its own as a segment rather than only as part of the running total. Clicking a player in the Deaths list opens a death recap of what killed them, which can also open by itself when you die; /tdm resetpos brings that window back to the middle if it has wandered somewhere unhelpful.",
    ["wn_344_dm_runrecap"] = "New — A run recap at the end of a dungeon: damage, healing, interrupts, deaths and avoidable damage taken for the whole group, opening on its own when the run ends, or brought back with /tdm recap. It builds itself up as you go rather than reading everything at the end, and that is not a preference — when a key actually finishes, the game will not let an addon read those values at all, so a recap written the obvious way could not even put the group in order. Instead a quiet snapshot is taken each time you drop out of combat, which is about fifteen times in a key and costs nothing you would notice. Anything unreadable at that moment is left alone rather than overwritten, so the last good figure for a player is never lost.",
    ["wn_344_dm_standalone"] = "Note — The meter is also published on its own as TomoDamageMeter. If you have that installed, the copy inside TomoMod stands aside as it loads and tells you so once at login, rather than two meters arguing over the same windows, settings and combat sessions. The bundled one always yields: installing the standalone is a deliberate choice, and the versions of it already out there have no way of knowing to step aside themselves.",
    ["wn_344_cds_window"] = "Fix — In the Cooldown Studio, the column of bar buttons down the left drew on top of the edit-mode button at the bottom of the window, and the labels spilled out of the buttons carrying them: 'Import : Buffs suivis' was simply wider than the box it sat in. The column had outgrown the room set aside for it when the import buttons were added, and nothing in this interface trims a piece that overflows — it just draws over whatever is beneath. The space is now worked out from what it has to hold, the buttons are wide enough for their own text, and the window is larger to pay for it. It also stops asking for more room than your screen has: it had only ever been told to stay on screen, which does nothing for a window that is bigger than the display, so on a smaller screen the whole left column could sit past the edge. It now fits itself to the space available, which is what makes making it bigger safe in the first place. AstralForge is built on the same window and gets the same treatment. On the dashboard, the Cooldown Studio card has also moved up next to the Tomo suite card, since both are ways out to something else.",
    ["wn_344_changelog_popup"] = "Fix — The What's New page could not lay out the notes it was showing: expanding a release wrote its paragraphs on top of one another. The reason is that a block of text has to be measured before the window has decided how wide it is, so a paragraph destined to wrap over six lines was measured as one, and everything below it was placed in the space that one line would have taken. Rather than teach the page to measure text, it now hands the release you picked to this very window, which has always been able to scroll. The page itself is now an index: every version as a button with the number of notes it holds, four to a row, newest first — fifty-nine of them in a single column made for a lot of scrolling to reach anything old. Two smaller things came with it. Reading an old release no longer counts as having read the current one, so looking up what changed in 3.2.1 out of curiosity will not swallow the notice for an update you have not seen yet. And this window's scrollbar had kept Blizzard's two brass arrows at either end of an otherwise green track; they are gone, and the bar uses the space they were holding.",
    ["wn_344_dm_config"] = "New — The meter's settings are now a proper Damage Meter page in TomoMod's options rather than a button that sent you to another window. The skin, the bar texture, the font and its size, the bar height and class-coloured accent; how transparent the window is, out of combat and on the detail panels; hiding realm names, keeping your own bar in view, bar tooltips, the combat timer and which side it sits on, resetting when you enter an instance, snapping the windows together; the automatic run and death recaps, and how many lines a report sends. Underneath, both this page and the meter's own window now go through one shared description of what has to be refreshed when a given setting changes — otherwise there would be two copies of that, and they would disagree the first time either one was edited. If a refresh does go wrong the setting is still saved, rather than showing you an error and quietly reverting what you just changed. Columns, adding windows and filtering by category deliberately stay in the meter's own window, since they act on one particular window rather than on everything; the page says so and takes you there. That window also used to open behind the options rather than in front of them, which is fixed.",
    ["wn_344_aura_secret"] = "Fix — Unit frame auras threw a stream of errors in patch 12.1 — 189 of them in a single session in the report that led to this. The game used to simply return nothing when an addon asked for a unit's auras in a state it did not approve of; it now refuses the request outright, and the refusal was not being caught, so it fired on every single aura event. It is caught now, and there is somewhere for it to go: the auras are read one at a time instead, which is slower but is the only route left open, and an aura that still appears beats one that produces an error. CooldownForge's buff watcher had the same problem from the other direction — the aura update the game sends can now arrive entirely unreadable, and merely testing whether it was a full update was enough to fail, another 38 times in one session. An unreadable update is now treated as a full one and everything is simply re-read, which is the only way to stay current when the details cannot be looked at.",

    -- =====================
    -- 3.4.3 — What's New
    -- =====================
    ["wn_343_changelog"] = "New — A What's New page in the options, holding every release TomoMod has ever shipped. Until now the release notes only ever appeared in the popup that follows an update, and that popup shows the version you have just moved to and nothing else — close it and the text is gone for good. The new page lists every version, newest first, and clicking one opens its notes. It reads the same notes the popup does, so there is no second list to fall out of date.",
    ["wn_343_cdf_resync"] = "New — Cooldown Studio: a bar you built from Blizzard's Cooldown Manager can now be brought back in line with it. Those bars were correct on the day you made them and had no way back afterwards, so a class rework left you comparing lists by hand. Resynchronise re-reads the category: abilities Blizzard has added since arrive, abilities it has dropped are removed. Everything you did to the bar survives — a spell that is still listed keeps its entry exactly as you tuned it, glow condition, spec visibility and per-entry effects included — and anything you added yourself is never touched and never removed, whatever Blizzard's list does. A spell you had added by hand that Blizzard later adds to the category stays yours rather than being claimed, so a later resync can never delete something you created.",
    ["wn_343_cds_icons"] = "Cooldown Studio: the list of what a bar tracks read 'Sort 384100' — correct, and no help at all. Each entry now shows its icon and its name, with the id kept in brackets after it. Until the game has cached a spell you still get the number on its own, which is the honest answer rather than a blank line.",
    ["wn_343_cds_scale"] = "New — Cooldown Studio: an icon scale slider, on both bar layouts. Making a bar bigger meant moving a width slider and then moving a height slider to exactly the same place; it is one control now. It is a view over the size you already had rather than a new setting, so there is still a single number underneath and nothing to keep in step. A button sets the icons back to square, keeping the size you were looking at rather than jumping back to the default. Once you deliberately set a width and a height apart the scale slider greys out — 'scale by 1.2' has no single answer at that point — and that button is what brings it back.",
    ["wn_343_iconsize_range"] = "Fix — Cooldown Studio: an icon size below 24 or above 64 looked accepted and was not. The bar rendered at the size you asked for and kept it, and then some later action — a resync, an import, a duplicate — quietly reverted it, with nothing to connect the change back to anything you had done. Meanwhile the separate width and height settings accepted 8 to 128 the whole time, so the same small icon was reachable through one control and refused by the other. There is one range now, 8 to 128, for all three. It is wider than before rather than narrower, so no bar you already have changes size.",
    ["wn_343_studio_shortcut"] = "New — A Cooldown Studio button on the dashboard, so opening the studio no longer means finding the CooldownForge panel first.",

    -- =====================
    -- 3.4.2 — What's New
    -- =====================
    ["wn_342_astralforge"] = "New — AstralForge, a full-screen designer for the pieces of a unit frame. Until now every part of a frame sat where TomoMod had decided it sat, and all you were given was a slider that pushed it a few pixels from there — so moving the name to the other side was not a setting, it was a number big enough to shove it across. You now drag each piece where you want it: which corner of the element attaches, and what it attaches to — the frame, the health bar, the resource bar, the info bar. It snaps to a small grid, lines up with the other elements as you pass them, and holding Shift drops it wherever you like. The sliders are still there for a two-pixel adjustment, and both write the same thing. It opens from the UnitFrames options, and like the Cooldown Studio it only loads when you ask for it. What you drag is a preview copy, never a real frame — the game protects those during combat, and editing one directly is what causes the interface problems TomoMod has spent two versions removing.",
    ["wn_342_af_nameplates"] = "New — Nameplates get the same designer, and for them it is entirely new ground: apart from the raid marker, nothing on a plate had a position setting at all. The name, the health value and percentage, the level, the classification icon and text, the cast bar with its icon, name, timer and shield, and the quest icon can each be placed where you want them. Your existing raid marker position is carried over unchanged, and everything else starts exactly where it already was. Two things are deliberately not draggable: auras, whose position is worked out from their place in the row rather than set, and the parts pinned to a bar's fill — a handle on those would claim to move something it cannot.",
    ["wn_342_af_props"] = "New — Opacity, scale and a text size override, per element. The size override starts at zero, meaning 'leave it as the module worked it out', so nothing changes until you say so. Only the settings a given piece can actually honour are shown: opacity means something on a piece of text, a scale does not, and a plain image takes neither of the two — you get the ones that apply to what you selected rather than a fixed row of sliders half of which do nothing.",
    ["wn_342_af_customtext"] = "New — Text you write yourself. Add up to six custom texts to a unit frame and four to a nameplate, write something like '[name] - [level]', and place it like any other element. The tokens are name, level, class, race and guild on a frame, and name, level, class, race and classification on a plate. Worth knowing why this is not simply the addon gluing words together: in Midnight the game hands out a unit's name and level as values an addon is forbidden to read, so anything as ordinary as joining a name to a dash would fail. Your template is turned into a pattern with the values passed through untouched and assembled by the game itself.",
    ["wn_342_af_presets"] = "New — Layout presets, and share strings. Save the whole layout of what you are editing under a name — every position, every opacity and scale, every custom text — apply it back later, or hand it to someone else as a string they paste in. Anything coming back in is checked the same way whether it is yours or a stranger's: values the addon does not recognise are dropped, an impossible anchor is refused before it reaches the game, and a layout that refers back to itself in a loop is broken apart. The worst a pasted string can describe is a layout.",
    ["wn_342_af_migration"] = "Your frames do not move. Every position you had set is converted into the new form together with the anchor the engine used to apply it against, so a converted profile and a brand-new one draw exactly the same frame. One old setting is dropped rather than converted — an aura offset the engine stopped reading back in 3.0.5. It has had no effect for several versions, and converting it now would move auras that are sitting precisely where you put them. Aura containers also stop keeping their position in a second place of their own: dragging one in game, placing it in the designer and setting it with the sliders now all write to the same setting, so they can no longer disagree.",
    ["wn_342_af_secret"] = "Fix — Opening AstralForge on a unit that was actually there could leave you with an empty window. The preview it builds was fed real data, and in the current game any piece of the interface whose content comes from protected information — a health value, for instance — also hides its own position and size from addons. Measuring those is the designer's entire job, so the very first measurement failed and took the preview down with it. The preview now runs on made-up data: an invented name, an invented health value, which nothing stops it from measuring and which look exactly like what you are laying out. Two safeguards come with it: anything that still cannot be measured is simply left without a handle instead of stopping everything around it, and if the preview cannot be built at all the window still opens with its element list, its inspector and its presets rather than opening empty.",
    ["wn_342_keysync_realm"] = "Mythic+: the party keystone list was empty for everyone on your own realm. Their key was received and stored the whole time — it just could never be found again. When someone's addon sends you their key, the game names them as 'Alice-Varimathras' whether or not that realm is yours, so every key is filed under a full name; but when TomoMod asks the game about the person standing next to you on your own realm, it gets back 'Alice' with no realm, and that matches nothing. This appeared with the new keystone sharing in 3.4.1, because the library it replaced hid that mismatch inside its own code. A name with no realm is now retried against yours, so a same-realm key is found again — and it is done once, in the place the keys are stored, rather than being something every screen that reads them has to remember.",
    ["wn_342_escape_keys"] = "Fix — While one of TomoMod's own windows was open, your keys did nothing: you could not move, and your abilities did not fire. Any window that closes with Escape has to ask the game for the keyboard, and a window holding the keyboard keeps every key to itself unless it deliberately passes the rest on — which it only did as a side effect of receiving a key it had no interest in, and never at all during a fight, which is exactly when losing your keys costs the most. Every key now goes straight through; the window keeps Escape alone, and only out of combat. With it comes the other half of the problem: a window now holds the keyboard only while it is actually on screen. One closed with Escape kept its grip afterwards, so the trouble outlived the window that caused it and the next window you opened inherited it. This covers every window in the addon that closes with Escape — the options, the installer, the loot window, the Mythic+ hub, TomoScore, the profession helper, the bag skin, the chat copy window and the Cooldown Studio.",
    ["wn_342_keysync_debug"] ="New — /tmt keysync. It prints which channel the sharing is using, whether you are in a guild, every key it currently holds, and then each member of your group with whether their key can actually be found. That last line is the whole point: a key that is stored but not found is a different problem from a key that never arrived, and from the party list the two look exactly the same — which is why the bug above took longer to identify than to fix. The command also asks your group for their keys as it finishes, so running it twice a second apart tells you whether anyone answered.",
    ["wn_342_cdf_viewer"] = "New — Cooldown Studio: build a bar from Blizzard's own Cooldown Manager in one click. Three buttons — Essentials, Utilities and Tracked Buffs — create a ready-made bar from the abilities Blizzard curates for the specialisation you are on, in its own order, and the tracked buffs come in as buffs rather than as cooldowns, so they appear while they are up and count down what is left of them. The list is read the moment you click and never stored: Blizzard keeps those three sets up to date through class reworks, so an imported bar follows the game instead of freezing a copy that would be right for one patch and quietly wrong from the next one on. Where a talent has replaced an ability with another, it is the replacement that lands on the bar, so the icon matches the one in your spellbook. It is a starting point, not something you are stuck with — what you get is an ordinary bar you can reorder, trim and restyle. And if your client has no Cooldown Manager, or Blizzard curates nothing for the specialisation you are on, the studio tells you so rather than handing you an empty bar.",

    -- =====================
    -- 3.4.1 — What's New
    -- =====================
    ["wn_341_style"] = "Mythic+ tracker: it was the last screen in TomoMod wearing colours of its own. Last version brought the end-of-run scoreboard in line and said the tracker you see during the key would not match until it got the same pass — this is that pass. It now uses the same green, the same text and the same borders as every other panel, on a near-black background with a mint cast. A font size setting comes with it, from 0.70 to 1.60, which grows the text without growing the panel.",
    ["wn_341_segments"] = "Mythic+ tracker: the timer is now three segments, one per chest, each counting down the time left before that chest is lost. Until now the panel showed the elapsed time and the gap to the full limit, and 'how long until +2 is gone' was arithmetic you did in your head between pulls. The segments are sized from the dungeon's real chest times, they read mint, yellow then red from left to right so the window being spent names itself by colour, and a spent one dims instead of disappearing so the bar still reads as a history of the run. If you would rather read the bar by shape than by colour, one setting paints all three in the same green.",
    ["wn_341_presets"] = "Mythic+ tracker: one fixed panel became three looks. Panel is what you already had. HUD drops the background and the header block and lists the objectives as plain text, slightly larger, on a condensed font. Minimal is three rows and nothing else — information, timer, forces — with the boss list gone and its tally moved up into the header, so you still know you are on 2 of 4 without spending four rows saying so. Everything a preset sets is also a switch of its own: background, header block, dungeon name, boss list, timer layout, segment colours, text size. Change one by hand and the preset says custom rather than pretending you are still on it.",
    ["wn_341_forces"] = "Mythic+ tracker: the forces bar could lie rather than admit it could not see. The game hides a growing number of values during a fight, and the bar was doing sums on them anyway — so a count it could not read came out as zero, and a bar that empties itself mid-pull does not look like missing data, it looks like the pull reset. It now holds the last figure it could actually read, and falls back in stages: exact counts, then the percentage alone, then frozen. It also shows what is left to kill rather than 730 / 1000, and states the time the count completed at.",
    ["wn_341_bossnames"] = "Mythic+ tracker: boss names came from a hand-written table that goes stale every season. Blizzard adds dungeons and reuses journal entries between them, so a list like that is wrong the day a patch ships and nothing warns you — the names simply degrade to 'Boss 1'. Names are now looked up live from the game, three ways in order: the map you are standing on, then the dungeon's own name matched against the journal, then the raw objective text if neither works. What it finds is remembered per dungeon, so it is learned rather than authored and cannot rot.",
    ["wn_341_splits"] = "Mythic+ tracker: you had nothing to compare a run against. Every finished key is now recorded per dungeon and per key level, and on the next attempt each boss shows how far ahead or behind your best you are. Forces get the same treatment: on each kill the tracker notes where your best run stood on trash at that point, and shows you the gap. A depleted run is recorded too — it may be the only reference you have for that dungeon, and a slow one beats none. Nothing is preloaded: an 'expected trash at boss 2' table shipped by an addon would be somebody else's route and would be wrong the day the dungeon is retuned. A button in the options clears what has been recorded.",
    ["wn_341_banner"] = "Mythic+ tracker: the end of a key passed without comment. There is now a banner — in time or depleted, the run time, the upgrades, and the margin in brackets. The margin is the number everyone says out loud when the key ends, and it was the one thing you had to work out yourself from a timer that had already stopped.",
    ["wn_341_options"] = "Mythic+ tracker: it had a second options window of its own, holding the same settings as the Mythic+ page in TomoMod's config — two places to change one value, and they drifted. It is gone: /tmt now opens the config on the Mythic+ page. Every other /tmt command is unchanged.",
    ["wn_341_legibility"] = "Mythic+ tracker: the text written on top of a filled bar was unreadable. Every label the tracker draws has a black outline behind it, and that text was almost black itself, so it dissolved into its own outline — the chest markers on the timer and the label on the trash bar were smudges while the white clock beside them stayed sharp. They are light now. Two smaller things went with it: a negative duration could print as a large positive one, so -3:40 appeared as 56:20, and the first boss no longer repeats its kill time twice on the same line.",
    ["wn_341_cds_taint"] = "Cooldown Studio: opening it could stop you logging out, by either of two routes. One line wrote to a table belonging to Blizzard — harmlessly, as far as the value went, but writing to it at all is enough for the game to distrust every window built from that table afterwards, the logout confirmation included. Separately, the 'copy the style from' popup handled Escape with its own copy of code that lives elsewhere in the addon, and that copy had drifted: it had lost its combat check and handed keypresses back to the game in a way that made the game menu refuse to open. Both are fixed, and the popup now shares the one implementation instead of keeping a private one. Neither ever affected a session in which you had not opened the Studio, which is why they took a while to pin down.",
    ["wn_341_keysync"] = "TomoMod was reporting itself as a source of interface problems dozens of times at every fight, without being one. The cause was a bundled library, LibOpenRaid, which works out whether the game is hiding a value by trying to read it and catching the error — the answer is right, but the game writes TomoMod's name into its log on every attempt, and that happens constantly. The library is no longer shipped. It was there for four keystone functions and nothing else, while also syncing cooldowns, gear, talents and durability, and it is the cooldown part that caused all of it. Keystone sharing is now TomoMod's own, in a file a fraction of the size: your key comes straight from the game, and the rest is shared with your group and guild directly, kept until the weekly reset. One thing that should now work for the first time: the party key list refreshes on its own when somebody's key changes — the old callback was wired in a way the library never actually called.",
    ["wn_341_buffskin"] = "The buff and debuff skin has been removed — the whole feature, along with its tab and its settings. It cannot be made to work on the current game: the buttons Blizzard uses for auras now hide their own size from addons, and putting a border on one raises an error inside Blizzard's code rather than in TomoMod's, where it could have been caught. On top of that those buttons are reshaped almost every patch, and this version alone spent five attempts chasing them. That is upkeep with no end, on the one part of the interface where Blizzard's own display is already fine. Your buff frame goes back to the default one, and the settings are cleared from your profiles since there is nowhere to carry them. If a skinned buff frame matters to you, a dedicated aura addon is the honest answer.",
    ["wn_341_auratracker"] = "The Aura Tracker has been removed. CooldownForge does the same job and does it better, and running two overlays that compete for the same corner of your screen was never going to end anywhere else. Its tab, its presets, its mover and its settings go with it, and a one-time cleanup drops the leftover settings from your profiles instead of carrying them around forever. If you had added spells to it by hand, they are not lost quietly: they cannot be converted automatically, so TomoMod lists them once at your next login, with their names, and you can recreate the ones you still care about in the Cooldown Studio.",
    ["wn_341_cds_reload"] = "Cooldown Studio: closing it can now reload your interface, and does by default. The Studio only loads when you ask for it, but the game cannot unload an addon again — a reload is the only thing that releases it, and it is also what clears anything the session may have picked up. The prompt waits for a sensible moment: never in combat, never during a key, never inside a dungeon or raid, and it comes back once you are out. You can turn it off in the CooldownForge options. Separately, leaving the Studio while the bars were unlocked used to strand them in edit mode with the resume button still floating on screen; both ways of closing the window now tidy up.",

    -- =====================
    -- 3.3.6 — What's New
    -- =====================
    ["wn_336_cdf_active"] = "CooldownForge: a buff that is up looked exactly like a spell that is recharging. Since an icon can track a buff instead of a cooldown, both states reached the screen as the same plain picture, and the only way to tell them apart was to read the number on them. Two new settings separate them: the cooldown sweep and the border can each take your class colour, or one you pick, while the tracked buff is active. Both are off everywhere by default, so nothing you have already built changes, and they only apply to entries that actually track a buff.",
    ["wn_336_cdf_threshold"] = "CooldownForge: the countdown can change colour when a spell is nearly back. Set a threshold in seconds, up to 60, and pick the colour it switches to underneath — reading a colour mid-fight is quicker than parsing a number. Zero turns it off and is the default. Where the game refuses to tell an addon how long is left, which is the case under restricted content, the timer keeps its normal colour instead of guessing: a countdown that guessed wrong would be worse than one that stayed plain.",
    ["wn_336_cdf_font"] = "CooldownForge: the text on your icons was locked to one font. The setting had existed in every bar since the feature shipped and nothing ever read it — the countdown, the stacks, the spell name and the mirrored timer were all hardcoded to TomoMod's own Poppins. You can now pick any font shared by your other addons, choose a thin, thick or absent outline, and give the countdown its own size independently of the stack and name text, so changing font no longer means abandoning your preset's sizing. Both size sliders run from 8 to 28 pixels now instead of 9 to 20. With no font-sharing addon installed the list holds Poppins alone and says so.",
    ["wn_336_cdf_glow_charges"] = "CooldownForge: glow can wait for every charge to come back. A two- or three-charge spell was ready or not as far as glow was concerned, so one charge out of three lit up exactly like three out of three. The new condition is answered from the recharge itself rather than by counting — the game hides the current count during a fight, and counting is precisely what cannot be done there. A spell with no charges falls back to plain readiness, so the condition is not silently useless on most of your entries.",
    ["wn_336_cdf_glow_stacks"] = "CooldownForge: glow can wait for a tracked buff to reach a number of stacks, set per bar and overridable per icon. The game does not publish a maximum for a buff, so the number is yours to give — 2 to 20 on a bar, up to 99 on a single entry. If the stack count cannot be read the glow stays off rather than firing on a guess, since a glow is something you act on.",
    ["wn_336_escape_taint"] = "Windows: pressing Escape could stop opening the game menu at all, leaving you unable to quit the game normally. Eight TomoMod windows closed on Escape by putting themselves on a list Blizzard walks through its game-menu code, and that code makes three calls the game refuses once anything in your session has upset it — so the menu never opened and Escape did nothing. Those windows now handle Escape themselves and never go near the game menu. Every other key still passes through. One thing to expect: on those eight windows Escape no longer closes them during a fight, because the call that makes this work is itself restricted in combat. Their close button still does.",
    ["wn_336_statusbar2"] = "New — Hide Blizzard Status Bar 2, in QOL, Automations. Edit Mode's second status bar sits beside the main one rather than inside it, so the option that hides Blizzard's status bars never reached it and nothing anywhere did. It is made invisible and click-through rather than deleted, which is what keeps it from causing errors: Blizzard still owns the bar, so it stays where it is in Edit Mode and you can still move it there. Unticking the option puts it back after a reload.",
    ["wn_336_ab_empty_refresh"] = "Action bars: with empty slots hidden, dragging a spell onto one left the button blank. The spell was really there and cast when clicked, but nothing was drawn on it until you reloaded — and dropping onto a bar blanked the neighbouring slots that had just been revealed for the drag. Hiding empty slots was changed last version to stop causing errors on Blizzard's buttons, and the new method left the bar unaware that a slot had been filled. It now notices, including when paging or a stance changes what a button points at.",
    ["wn_336_uf_aura_growth"] = "Unit frames: auras only ever grew downwards. The direction setting covered left and right, and the vertical half of the question had no setting at all — so a frame sitting low on your screen sent its second row of debuffs off the bottom edge with nothing anywhere to stop it. A vertical direction now sits beside the horizontal one on every unit's Auras tab, and the rows can stack upwards instead. Downwards stays the default and nothing you have already set up moves; the frame itself does not move either, the aura block simply grows the other way.",
    ["wn_336_ts_palette"] = "Mythic+: the end-of-run scoreboard was the one screen in TomoMod with colours of its own — a cyan accent where the rest of the addon is green, on a blue-tinted background where the rest is neutral. It came from before that board was part of TomoMod and had never been brought in line, so it read as somebody else's window. It now takes the same theme as everything else. Two colours stay as they were on purpose: the 'in time' bar and its text keep their own green, because on a panel that is already green everywhere an 'in time' marker in the same green stops telling you anything. The tracker you see during the key itself is untouched for now, so the two will not match until it gets the same pass.",
    ["wn_336_cdf_talent"] = "CooldownForge: an icon can be tied to a talent — shown only when it is taken, or only when it is not. The second half is as useful as the first, since a build that drops a talent usually gains something in its place, and both icons can now sit in the same bar with only the relevant one on screen. You give the spell the talent grants rather than a node number: nodes are renumbered at every talent rework, spells are not, so the condition survives a patch. It also follows your loadouts now — swapping talents announces itself differently from editing them, and only one of the two was being listened to, so a condition could keep answering with the previous build until something unrelated forced a refresh.",

    -- =====================
    -- 3.3.5 — What's New
    -- =====================
    ["wn_335_cdf_border"] = "CooldownForge: dragging the border thickness slider made the border disappear instead of thickening it. Each style setting was stored as one block, and the editor writes one field at a time — so setting the thickness threw away the border mode sitting next to it, and without a mode the icon was drawn with no border at all. Picking a colour did the same thing, and picking a mode quietly reset the thickness. Those settings now keep the fields you did not touch. No bar changes on its own; set the value again and you get what you asked for the first time.",
    ["wn_335_cdf_border_paint"] = "CooldownForge: even once it stopped disappearing, the border was barely visible and 1 pixel looked exactly like 4. The outline is drawn just inside the icon's edge, and the icon's picture covered the whole of it — so the border was painted and then hidden underneath, and making it thicker only buried more of it. The picture now stops short of the border and leaves it room. Two things to expect: a bordered icon shows its picture very slightly smaller, which is what a border costs, and a thickness you set while the slider appeared to do nothing will suddenly be visible — so a bar left on 4 will look much heavier until you set it to what you actually wanted. Icons with no border are unchanged.",
    ["wn_335_cdf_preset"] = "CooldownForge: touching any fine setting quietly turned your bar into a Tomo one. Picking a border colour on a Net or Verre bar switched its style to 'Custom', and Custom was not a real style — so the icon fell back to Tomo and the base you had chosen was gone. Which preset a bar uses and whether it has fine settings are now two separate things: changing the preset keeps your fine settings on top of the new one, and adjusting a fine setting leaves the preset alone. Bars already saved as Custom become Tomo with their settings kept, which is what they were already being drawn as, so nothing changes on screen.",
    ["wn_335_cdf_thickness"] = "CooldownForge: the border thickness slider goes up to 10 instead of 4. Four was a fair limit while the border was invisible; now that it is actually drawn it is not. Bear in mind the border takes its width out of the icon picture, so 10 on a small icon leaves very little of it.",
    ["wn_335_cdf_target"] = "CooldownForge: a bar can now depend on whether you have a target, alongside the existing combat, instance, group and raid conditions and with the same three choices — don't care, require it, require the opposite. For the bar you only want up while you are actually on something, or the utility bar that should get out of the way the moment you pick a target.",
    ["wn_335_cdf_dim"] = "CooldownForge: a bar whose visibility condition is not met can now fade instead of disappearing. Pick 'reduce opacity' instead of 'hide' and set how faint it should go, from 5% to 95%. The faded bar is still live — it keeps tracking cooldowns rather than freezing — so 'in combat = yes' with this option leaves you a readable, half-visible bar out of combat instead of one that comes back already out of date. Hiding stays the default and nothing changes for bars you have already set up.",
    ["wn_335_cdf_iconwh"] = "CooldownForge: icons no longer have to be square. Width and height are separate sliders now, 8 to 128 pixels each, instead of one size doing both — wide flat icons for a row across the top of the screen, tall narrow ones for a column beside your frames. Bars you have already built do not move: the new values start unset, and unset means 'keep the old square size'.",
    ["wn_335_cdf_aura"] = "CooldownForge: an icon can track a buff instead of a cooldown. Switch an entry to 'tracked buff' and it stays off screen while the buff is absent, then appears with its remaining time and stacks while it is up — so a proc can sit on the same bar as the cooldown that grants it. You can also name a different buff ID, for the procs that are granted by one spell and applied as another. Under Mythic+ the game hides most of what an addon can read about a buff; that is handled separately below.",
    ["wn_335_cdf_secret"] = "CooldownForge: a tracked buff disappeared the moment a fight started and came back the moment it ended. Every lookup went through the buff's spell ID, and in Midnight the game hides that number during combat — measured as fully readable out of combat against 6.5% in it, with every tracked buff going missing in the very frame the pull began. The game does hand out the ID once, at the moment the buff lands, together with a reference to that particular application; TomoMod now remembers the pair and asks about the application from then on, which the game keeps answering. The remaining time and the stack count are back in Mythic+ too, read the same way — the earlier note saying tracked buffs work there but without a timer is no longer accurate.",
    ["wn_335_cdf_aura_sources"] = "CooldownForge: tracked buffs are found through two paths now instead of four. Each had been added to cover a case the one before it missed, and nothing said which was actually doing the work — so they were measured over some 12 700 lookups each. Two carried the whole feature, and they cover opposite halves of it: one works during a fight, the other outside it. The two that produced almost nothing were removed, along with a sweep of all your buffs that ran every frame for every bar. One more gap is closed with them: a buff that only gains a stack is reported by the game as an update rather than as a new buff, so a proc first noticed that way mid-fight was never registered at all. What remains is a limit of the game, worth knowing rather than hunting for: during a fight it only names some auras. A buff already up when the fight starts is tracked normally; one applied in the middle of it may not be identifiable, and its icon stays hidden. There is no setting for that, and the tracked buff option now says so on the spot.",
    ["wn_335_cdf_viewer_source"] = "CooldownForge: a proc that lands in the middle of a fight is now tracked as well — the limit described just above is largely lifted. The game refuses to tell an addon which buff that is, but it has been drawing it on your screen the whole time: Blizzard's own Tracked Buffs display is not subject to the restrictions an addon is. TomoMod now reads that display — whether the icon is up, the time left on it, its stack count — instead of asking a question the game will not answer during a fight. Nothing is hardcoded and nothing protected is touched; it reads the same picture you are looking at. It only covers buffs Blizzard's Tracked Buffs display actually carries: for anything else the two previous methods answer exactly as before, so this adds cases and takes none away. Worth knowing if you use the new per-bar hiding: hiding a Cooldown Manager bar does not cost you this, because hiding works by transparency and the bar keeps running underneath. One visual detail to expect during a fight: where the game withholds the numbers but still draws the countdown, TomoMod mirrors that figure onto your icon — you get the time remaining as a number, without the sweep behind it, and it steps rather than ticks, because the bar refreshes on events instead of running a timer.",
    ["wn_335_cdf_aura_timer"] = "CooldownForge: a tracked buff could appear with no timer and no swipe even when the game had told us exactly how long it had left. There were two ways to put a countdown on the icon, and the wrong one was being preferred: the one that took a duration object, which the game hands back in a different shape from the one the cooldown display expects. It accepted it, drew nothing and reported no error — so the safety net meant to catch that failure never triggered, and the numeric path that would have worked was never reached. Readable numbers are now used first, and the object only when the game refuses to give the numbers. If you had tracked buffs showing as a bare icon, they get their timer and their stacks.",
    ["wn_335_cdf_glow_aura"] = "CooldownForge: the glow condition 'while a buff is active on you' went dark for the length of every fight, and nobody had connected it to the tracked buffs. It asked the game for your buff the same way tracked buffs originally did — the way that stops answering the moment combat starts — so the glow simply stopped, which reads as a glow that was never set up properly rather than as a bug. It now finds buffs exactly the way tracked buff icons do, so the two can no longer disagree about what you are carrying.",
    ["wn_335_microbar"] = "New — Micro Bar: Blizzard's little row of menu buttons becomes a bar of your own. Choose which buttons appear and in what order, horizontal or vertical, how many per line, their size, spacing, scale and opacity, and place it anywhere with the Movers panel. It can stay on screen, appear on hover, or appear on hover but stay up during combat. Icons can take your class colour, a colour you pick or the game's original look, with optional desaturation and a zoom under the cursor. Each button simply forwards your click to Blizzard's own, so everything keeps working in combat and nothing breaks when a new panel is added to the game. The originals also keep running underneath, so their alerts, their greyed-out states and their keybinds can be mirrored onto your buttons — with a choice of four alert glows, dimming for what is currently unavailable, and the keybind drawn on the icon.",
    ["wn_335_cdf_aura_gate"] = "CooldownForge: a tracked buff no longer has to be a spell you can cast. Before showing any icon the bar checks that the entry applies to you, and for a spell it checked your spellbook — which is right for a cooldown and wrong for a buff. Proc buffs are handed to you by a talent or applied by another spell, so your spellbook says you do not have them, and the entry was thrown out before anything looked at whether the buff was actually up. The icon never appeared — which is most of what tracked buffs are for. A tracked buff is now judged on the buff.",
    ["wn_335_cdf_aura_link"] = "CooldownForge: tracking a proc no longer means hunting down the buff's own spell ID. An ability and the buff it grants are almost never the same ID, so entering the ability — the obvious thing to do — watched a buff nobody ever has, and the icon simply stayed off screen. An entry now also tries whatever the game links to the ID you typed: Blizzard's Cooldown Manager already works this out for its own Tracked Buffs viewer, and TomoMod reads the same answer. Nothing is hardcoded, so it follows a patch that re-points a proc and a talent that swaps one, on its own. The optional buff ID field still works and still takes priority, for the cases the game does not link.",
    ["wn_335_cds_reorder"] = "Cooldown Studio: entries in a bar can be moved up and down. Reordering your icons meant removing an entry and adding it back at the end, then rebuilding everything after it. If the options panel is open on the entry you move, it follows that entry instead of staying on the slot — it used to end up editing whichever one had taken its place.",
    ["wn_335_mplus_teleport_override"] = "Mythic+: a dungeon teleport sitting in your spellbook could still be reported as not learned — the row greyed out, the tooltip saying it was unavailable, the click doing nothing. When a dungeon comes back in a later season, Blizzard re-issues its teleport as a different spell: Skyreach's is now cast as 'Voie des cieux', not the Warlords spell TomoMod's table lists. The check only ever asked about the listed one, so owning the current spell looked exactly like owning nothing. It now also asks the game which spell replaces the one it knows about, and accepts either — by spell number rather than by name, so it works whatever language your client runs in, and it follows a future season that re-points a teleport without needing an update.",
    ["wn_335_ab_taint"] = "Action Bars: the 'show empty button slots' option was the source of a burst of blocked-action errors on the bottom-left bar's buttons — errors the game blamed on whichever addon happened to be running at that moment, most recently making it look like Cooldown Studio was at fault. Showing the empty slots was done by writing into Blizzard's own button state and forcing the buttons shown, which the game then refuses to touch afterwards. It now uses the game's own 'always show action bars' setting, and bars that should not show their empties are made invisible and click-through instead. Blizzard keeps control of its buttons. Two things worth knowing: that setting is global, so it switches on as soon as one of your bars wants empty slots, and if you had turned it on yourself in Blizzard's options it will be turned back off once no TomoMod bar needs it. Dropping a spell onto an empty slot still works exactly as before.",
    ["wn_335_cdm_viewers"] = "Cooldowns: Blizzard's four Cooldown Manager bars can now be hidden one at a time, from the Cooldowns panel next to the Cooldown Studio button — Essential, Utility and the two Tracked Buffs displays each have their own tick. Ticking one takes that bar off the screen and out of TomoMod's placement mode and leaves the other three where they are. It replaces a single tick that did not hide anything: it only stopped TomoMod restyling those bars, so they stayed on screen in Blizzard's own look — a box labelled 'hide the Cooldown Manager bars' that made them more noticeable rather than less. A hidden bar is made invisible and click-through rather than deleted: it is still Blizzard's bar, still running underneath, and whether it exists at all is still decided in Blizzard's Edit Mode. Unticking puts it back exactly where you had placed it. The switch in CD & Resources is untouched and answers a different question — whether TomoMod dresses these bars at all, rather than which of them you want to see. The two also work together now: hiding a bar keeps working when the Cooldown Manager module itself is switched off, which had been the one combination where the tick was saved and never applied to anything — and which is exactly what someone who wants these bars gone is likely to try.",
    ["wn_335_cdf_entry_spec"] = "CooldownForge: an entry's specialisation could only be chosen at the moment you added it. After that nothing anywhere let you change it — an icon added on the wrong spec, or added before you decided it should only show on one, had to be deleted and re-added, which also meant losing its place in the bar. The dropdown now sits on the entry itself, both in Cooldown Studio and on the Cooldowns settings page.",
    ["wn_335_scrollbar_click"] = "Settings: the scrollbar in the settings window can be seen and used now. It was five pixels of dark grey on a dark panel — almost impossible to hit, and hard to notice at all, so the mouse wheel was in practice the only way down a long page. Clicking the track above or below the handle now jumps most of a screenful in that direction, and the handle can be grabbed without having to aim at it precisely. It also looks different, deliberately: a little wider, in a lighter grey, with a thin dark line down its inner edge so it stands out from the panel behind it. The text boxes that hold import and export strings have the same bar, and now match. This applies to every page in the settings, not just one.",
    ["wn_335_cds_tabjump"] = "Cooldown Studio: changing almost anything threw you onto a different tab. Editing an icon's style dropped you on Sharing, ticking a visibility condition dropped you on Layout. The editor rebuilds itself after nearly every change and reopened the tab it had remembered — but it only remembered a tab the very first time that tab was built, so it was stuck on whichever one you had opened last for the first time, and returning to a tab you had already visited never updated it. It now follows the tab you are actually on.",

    -- =====================
    -- 3.3.4 — What's New
    -- =====================
    ["wn_334_studio_reasons"] = "Cooldown Studio: the 'Open Cooldown Studio' button could do nothing at all. Every possible reason the editor failed to load was reported as the same message — 'not installed' — including the most common one by far, which is that it is installed and simply left unchecked in your addon list. Each reason now says what it is and what to do about it.",
    ["wn_334_studio_enable"] = "Cooldown Studio: if the only problem is that it is unchecked in the addon list, clicking the button now ticks it and opens the editor. Where the game insists on a reload first, it says so instead of sending you off to find the setting yourself.",
    ["wn_334_studio_preflight"] = "Cooldown Studio: the card in the Cooldowns tab tells you the editor cannot open before you click it, not after. The button stays clickable on purpose — for an unchecked addon, clicking it is the fix.",
    ["wn_334_studio_init"] = "Cooldown Studio: an editor that loaded but failed to start up swallowed your click without a word. It now says it loaded but could not initialise, and why.",
    ["wn_334_studio_toc"] = "Cooldown Studio: the sub-addon now shows the TomoMod icon, a category and the addon's real version number in your addon list. It was still declaring 1.0.0 with no icon, which made it look like somebody else's addon that happened to share the name.",
    ["wn_334_package_builder"] = "Packaging: the download is now built by a script that refuses to produce it if the Cooldown Studio ends up inside the TomoMod folder instead of beside it. WoW only looks at the top level of your AddOns folder, so a Studio packed one level down is a Studio nobody can see in their addon list — which is the situation half of the fixes above exist to diagnose.",
    ["wn_334_diag_export"] = "Diagnostics: the export window asked you to copy the report, then put the tracker's address in its title — an address you could only take by throwing away the report you had just copied. It now switches between the report and the link, tells you which one it just put in your clipboard, and shows the address on screen in plain text so you can simply read it.",
    ["wn_334_diag_reminder"] = "Diagnostics: the window now states that your report is saved and can be reopened at any time with /tmdiag tracker, so taking the link first costs you nothing. Closing it also prints the address in chat once per session, in case you closed it too fast.",
    ["wn_334_presets_roles"] = "Presets: the Tank, Healer and DPS presets wrote three or four settings each and took everything else from the shared base — three archetypes that were the same configuration under different names. Each one now writes a full role setup across party and raid frames, nameplates, target auras, resources, cooldowns and castbars: wide threat-coloured plates and numeric threat for tanks, much larger frames with HoTs, dispels and shields for healers, taller resource bars and only your own debuffs for damage.",
    ["wn_334_presets_reset"] = "Presets: switching from one to another kept the previous one's settings. A preset only ever wrote its own changes, so anything it did not mention stayed where the last one left it — going from Tank to Healer left you healing with tank-mode nameplates. The shared base now carries a value for every setting any preset can touch and is written first every time, so applying a preset gives the same result whatever you had before it.",
    ["wn_334_presets_cards"] = "Dashboard: the presets are cards now instead of four coloured buttons with nothing on them but a name. Each shows its role icon, its tagline and three points of what it actually changes, with the full description on hover — and the one you are currently running is marked Active, which nothing on that panel used to tell you.",
    ["wn_334_role_badges"] = "Settings: sections that matter to a particular role now carry a small tank, healer or damage icon in their header — heal-over-time and dispel displays, defensive cooldowns, tank mode, interrupt tracking, threat text and the rest. Hovering the icons names the roles.",
    ["wn_334_role_filter"] = "Settings: a role focus bar was added at the top of the sidebar — All, Tank, Healer, DPS. Picking one keeps the settings for that role at full brightness and dims the others. It dims rather than hides on purpose: an option you already know the location of is still exactly where you left it, whatever focus is active. Your choice is remembered between sessions.",
    ["wn_334_chat_history_settings"] = "Chat history: the only thing you could do with it was turn it on. It has a section of its own now — how long messages are kept (1 hour to 3 days, or no limit), how many lines are stored (10 to 500), and a session marker printed after the restored lines so everything below it is clearly from the current session. The stored limit was also off by one: it said 128 lines and kept 127.",
    ["wn_334_chat_history_delay"] = "Chat history: the restored lines used to print at exactly the moment addon load messages and Lua errors reach the chat, burying up to a full page of them under the replay. The history now waits a couple of seconds before appearing — adjustable, or zero for the old behaviour.",
    ["wn_334_chat_history_channels"] = "Chat history: which channels are kept — whispers, guild, officer, party, raid, instance, channels, say, yell, emotes — has been a setting since the feature shipped and had never appeared anywhere in the interface. It is on the panel now. An unchecked channel is not recorded at all rather than merely left out of the replay, so re-ticking one does not bring back what went by while it was off.",
    ["wn_334_chat_history_clear"] = "Chat history: there is now a button to delete everything stored, behind a confirmation, and turning the feature off clears what is already saved instead of leaving every line sitting in your saved variables. The panel says so before you untick it — along with the fact that history is stored account-wide and therefore shared by all your characters.",
    ["wn_334_roles_guides"] = "Roles: a new Roles category, with a guide page for tanking, healing and damage. Each one explains what actually matters for that role, and every point carries a button that opens the panel holding the setting and highlights it. The page also applies that role's preset and switches the sidebar's role focus in one click.",
    ["wn_334_search_nested_tabs"] = "Config search: a result inside a nested tab — raid frame HoTs, resource bar colours, anything a panel puts behind its own second row of tabs — opened the right category and then landed on its first tab, not the one holding what you searched for. The index only ever stored the innermost tab name, which the outer tab bar could never match. It records one name per level now, and each tab bar reads its own.",
    ["wn_334_search_index_all_tabs"] = "Config search: most of the settings were never in the index at all. Pages you have never opened are built once, out of sight, so that searching can find them — but a panel only builds its first tab, so everything sitting behind a second or third sub-tab, which is the bulk of the interface, could not be found by searching for it. Every tab is walked now. That is far more to build, so it happens in the background a few milliseconds at a time instead of freezing the game on your first search, and a list of results already on screen refreshes itself once it is done.",
    ["wn_334_search_index_duplicates"] = "Config search: panels that reuse one page across several tabs — every castbar unit, every unit frame — collapsed into a single result. The index only kept the innermost tab name, so the target castbar and the focus castbar wrote the same entry over the same section and every copy but the first disappeared. Entries now carry the full path, and each unit's sections are listed on their own.",
    ["wn_334_roles_deeplink"] = "Roles: the buttons on the guide pages opened the right category and then left you on whatever tab you had last used. They looked their setting up in the search index, and those settings — raid frame HoTs, party defensives, tank mode — were exactly the ones the index was missing. Each button now names its own route, tab by tab, so it lands on the right page and highlights the section, on a freshly started client and whatever you were looking at before.",
    ["wn_334_cr_detection"] = "Class reminder: it was reading the stance bar by position. Cat was slot 2, Bear slot 1, Moonkin slot 4 — but where a form sits on that bar depends on your talents, so on any build where it moved, the reminder was comparing your actual form against an unrelated slot: telling you a form was missing while you were standing in it, or staying quiet while you were out of it. Forms are matched by spell now. Warriors get their three stances, one per specialisation, instead of one entry covering three bar slots on every spec. And paladin auras were being looked for among shapeshift forms, where they were never going to be found — they are buffs, and are checked as buffs.",
    ["wn_334_cr_false"] = "Class reminder: some reminders could not be cleared at all. Evoker tracked a single Blessing of the Bronze buff, and that spell applies a different one to each class — so twelve classes out of thirteen were told they were missing a buff they were carrying, for as long as the module was on. Same for the talent versions of Mark of the Wild, Arcane Intellect, Moonkin Form and Shadowform: only the base version was known, so anyone running the variant was reminded about a buff they already had.",
    ["wn_334_cr_icons"] = "Class reminder: it was a pulsing line of text in the middle of the screen naming what was missing. It is a row of icons now, one per missing buff, form, stance or aura, and out of combat you can left-click one to cast it instead of reading its name and going to find it on a bar. Middle-click drops a reminder until your next loading screen, for the buff you have decided you are not taking today. Nothing is clickable in combat, on purpose — a row that stayed armed would be lying about what pressing it does.",
    ["wn_334_cr_options"] = "Class reminder: icon size, spacing, row scale, opacity, the label and its size, and a glow with its own colour. The two position sliders are gone — the row is placed with the mover like everything else that moves, and it has its own entry in the Movers panel. If you had moved it with the sliders, that position is carried over once.",
    ["wn_334_cr_panel"] = "Class reminder: the settings page opens on a live preview of the row, drawn by the module itself, so every slider moves the thing you are looking at. Clicking an icon takes you to its toggle, its label to the label options, the space around it to the sizing sliders. And the list of supported classes — a paragraph of text per class — is a grid now, one cell per tracked buff or form, coloured by class, each one a switch you can turn off for anything you would rather not be reminded about.",
    ["wn_334_cr_enchants"] = "Class reminder: weapon imbues were not tracked at all. Flametongue, Windfury, Earthliving, Tidecaller's Guard and Thunderstrike Ward each get their own reminder, and the two Lightsmith rites share one, since they are mutually exclusive and either satisfies it. Imbues are not auras, so the game never announced them the way it announces a buff — they now clear the moment you apply one instead of waiting for something unrelated to refresh the row.",
    ["wn_334_cr_poisons"] = "Class reminder: rogue poisons, one reminder per category rather than per poison — Lethal and Non-Lethal. What matters is whether the slots are filled, so it counts how many of that category are active against how many you can actually apply, one or two with Dragon-Tempered Blades. No list of builds to keep up to date, and nothing to reconfigure when you change talents.",
    ["wn_334_cr_shields"] = "Class reminder: shaman shields are tracked, and Elemental Orbit is taken into account rather than ignored. With the talent you carry Earth Shield on yourself and one of the other two, so both are checked; without it, any one shield is enough. The reminder names the category and its icon points at the right shield for your specialisation — Water for Restoration, Lightning otherwise.",
    ["wn_334_cr_context"] = "Class reminder: you can now choose where it shows up — everywhere, in dungeons and raids only, or in a group only. It is hidden in cities and inns by default, since that is where you are about to reapply everything anyway, and it stays quiet while you are dead, in a vehicle or flying on a mount: states where nothing on the row can be pressed.",
    ["wn_334_cr_group"] = "Class reminder: it can watch the group too. Turn on 'also remind when a group member is missing a buff' and a group buff you are carrying still raises its reminder while someone in range is without it — the case it always missed, since having the buff yourself says nothing about the rest of the party. Only members who actually want the stat count, and only out of combat: another player's auras cannot be read during a fight, and guessing would leave a reminder on screen for the whole pull. Off by default, because watching everyone's auras is not free.",
    ["wn_334_cr_perf"] = "Class reminder: it re-scanned your auras and your stance bar once a second, forever, whether or not anything had changed. The game already announces a buff gained, lost or expired, and the stance bar has its own events, so none of that polling was needed. It reacts to events now, and also notices a talent or spellbook change — which is when the set of forms you can be reminded about actually moves.",
    ["wn_334_uf_preview_engine"] = "Unit frames: the settings preview was a mock-up. It drew its own fake bars from the same numbers but with its own code, so it could disagree with what you actually got in game — and it did. It is built by the same functions that build your real frames now: bar texture, fonts, borders, the info bar, element offsets, the aura grid, enemy buffs and threat all come from the real engine, and the preview can no longer drift away from it.",
    ["wn_334_uf_preview_live"] = "Unit frames: the preview shows your actual units. When the unit exists — your target, your focus, your pet — the frames are fed real data and tagged LIVE; when it does not, they fall back to simulated values tagged SIM. There is also a Fit / 1:1 toggle, so you can check the frames at their true pixel size instead of the scaled-down strip.",
    ["wn_334_uf_texture_live"] = "Unit frames: changing the bar texture did nothing until you reloaded — it was only read when a frame was first built. Same for the duration numbers on auras. Both apply as you change them now, on your real frames and not only in the preview.",
    ["wn_334_tmkeys"] = "Mythic+: /tm keys opens the scoreboard on your actual group — everyone's name, class, M+ score and the keystone they are holding. Until now that board only appeared by itself at the end of a run, and the one command that opened it by hand showed sample data rather than anyone real. Deciding which key to run was exactly the moment you could not look at it. It works outside a dungeon, which is where you need it.",
    ["wn_334_score_roleicon"] = "Mythic+: every row on the scoreboard now shows a role icon beside the specialisation icon, in the same colours as the role presets and the settings badges. The spec tells you what someone brought, the role tells you what they are doing with it, and a keystone list you read before pulling wants both.",
    ["wn_334_score_spec"] = "Mythic+: your own specialisation was missing from your row on the scoreboard — the game does not report it through the same call it uses for everyone else. It is read directly now. Players sharing a role also came out in a different order every time the board was opened outside a run, since the damage figure that normally separates them is zero for everybody there; ties now fall back to keystone level, then score, then name.",
    ["wn_334_mplus_teleports"] = "Mythic+: dungeon teleports you had earned were shown as not learned. The panel and the scoreboard greyed the dungeon out, the tooltip said the teleport was not available, and clicking the row printed 'not learned' and cast nothing. The test it used only reports spells your class or your pet grants you, and dungeon teleports come from achievements — so it answered no for every single one of them, whatever was actually in your spellbook. Reported for Skyreach, and it applied to the whole list. The teleports work from the panel now.",
    ["wn_334_delete_confirm"] = "Delete confirmation: the feature that types the confirmation word for you was still reaching for a part of that window Blizzard removed in 11.2, and only worked through a fallback that guesses the window's internal name. It now asks the game for the text field the supported way, with the old routes kept behind it — so it keeps filling the box whatever Blizzard does to that popup next.",
    ["wn_334_friends_removed"] = "Contacts: the skin for the friends window has been removed, along with its tab in the settings. Blizzard is rebuilding that window in 12.1, and the skin worked by reaching for several dozen of its individual parts by name — parts the rebuild is free to move or rename. That does not age gently: it leaves a half-stripped window on patch day, for you rather than for us. The skin was off by default; if you had it on, the window simply goes back to Blizzard's own look. The Contacts button in the chat sidebar is unaffected.",

    -- =====================
    -- QOL: Companion Status (pet reminder)
    -- =====================
    ["tab_qol_companion"]             = "Pet Reminder",
    ["section_companion"]             = "Companion Status",
    ["info_companion_desc"]           = "Shows a reminder when your pet is missing or dead. Only appears for specs that actually use one: Beast Mastery and Survival hunters, all warlocks, and Unholy death knights. Lone Wolf and Grimoire of Sacrifice turn it off by themselves.",
    ["info_companion_unavailable"]    = "The module has not finished loading yet. Reopen this tab in a moment.",
